globalThis.FFRefereePassages=[{"id":"sibal:record","title":"Ferkul et al., LUCI flight and ground comparison","url":"https://ntrs.nasa.gov/api/citations/20250010653/downloads/ASGSR%202025-LUCI-Ferkul-Presentation-v2-20250010653.pdf#page=34","locator":"PDF pp. 4, 12, 16, 19, 23–27, 33–34, 42. Page 34 compares SIBAL flame width.","text":"LUCI burned 5 × 30 cm cotton–fiberglass fabric downward in simulated lunar gravity. Its flame base advanced at 0.9 mm/s versus 1.5 at 1 g, and its tip at 1.1 versus 2.8 mm/s. Fabric extinction occurred about 45 seconds later in the partial-gravity run."},{"id":"sibal:reason","title":"Ferkul et al., matched parabolic and drop-tower tests","url":"https://ntrs.nasa.gov/api/citations/20260001966/downloads/Ferkul-Lunar%20and%20Planetary%20Science%20Conf%202026%20v2.pdf#page=21","locator":"PDF pp. 21–22, day 2, parabola 29. Aircraft observation window 20 seconds.","text":"A separate 20-second aircraft test matched the fuel, 5 cm width, direction, approximate gravity and initial atmosphere. It measured base spread of 0.86 mm/s versus 0.92 on LUCI. The centrifuge drop test reported 1.1 mm/s."},{"id":"sibal:limit","title":"Ferkul et al., LUCI flight and ground comparison","url":"https://ntrs.nasa.gov/api/citations/20250010653/downloads/ASGSR%202025-LUCI-Ferkul-Presentation-v2-20250010653.pdf#page=34","locator":"PDF pp. 4, 12, 16, 19, 23–27, 33–34, 42. Page 34 compares SIBAL flame width.","text":"The rocket spun, two fuels burned in a shared chamber, and oxygen declined from about 20% to 18% over the fabric observation while the 1-g comparison stayed near 20%. The 45 seconds is an approximate difference for this comparison. It does not give a universal gravity multiplier."},{"id":"sibal:next","title":"Ferkul et al., LUCI flight and ground comparison","url":"https://ntrs.nasa.gov/api/citations/20250010653/downloads/ASGSR%202025-LUCI-Ferkul-Presentation-v2-20250010653.pdf#page=34","locator":"PDF pp. 4, 12, 16, 19, 23–27, 33–34, 42. Page 34 compares SIBAL flame width.","text":"A proposed research test is to repeat the pair with one material per chamber, matched initial gas and ignition, measured local flow, synchronized oxygen and images, and a fixed definition of extinction. Observe through extinction or record that the run ended first."},{"id":"sibal:decision","title":"Ferkul et al., LUCI flight and ground comparison","url":"https://ntrs.nasa.gov/api/citations/20250010653/downloads/ASGSR%202025-LUCI-Ferkul-Presentation-v2-20250010653.pdf#page=34","locator":"PDF pp. 4, 12, 16, 19, 23–27, 33–34, 42. Page 34 compares SIBAL flame width.","text":"Use the LUCI fabric pair for extinction. Use the aircraft comparison for early spread."},{"id":"saffire:record","title":"Ferkul et al., Saffire-II composite results","url":"https://ntrs.nasa.gov/api/citations/20170008805/downloads/20170008805.pdf#page=25","locator":"PDF pp. 24–25, Table I p. 29, sample 2-7 and note ii.","text":"An upstream 5 cm PMMA strip overlapped Nomex HT90-40. At about 22.1% oxygen and 20 cm/s concurrent flow in orbital microgravity, PMMA was consumed. The first centimetre of Nomex was damaged and the first five were blackened. Table I records zero Nomex burn length."},{"id":"saffire:reason","title":"Ferkul et al., Saffire-II composite results","url":"https://ntrs.nasa.gov/api/citations/20170008805/downloads/20170008805.pdf#page=25","locator":"PDF pp. 24–25, Table I p. 29, sample 2-7 and note ii.","text":"The authors distinguish the PMMA flame plume from ignition of the downstream fabric and identify deposited soot as a possible contributor to discoloration."},{"id":"saffire:limit","title":"Ferkul et al., Saffire-II composite results","url":"https://ntrs.nasa.gov/api/citations/20170008805/downloads/20170008805.pdf#page=25","locator":"PDF pp. 24–25, Table I p. 29, sample 2-7 and note ii.","text":"The 140 s in the table belongs to the composite experiment. Related 1-g tests of externally heated HT90-40 found burning supported by a PMMA flame under some conditions. Changing the grade, pressure, oxygen or external heating changes the scope."},{"id":"saffire:next","title":"Ferkul et al., Saffire-II composite results","url":"https://ntrs.nasa.gov/api/citations/20170008805/downloads/20170008805.pdf#page=25","locator":"PDF pp. 24–25, Table I p. 29, sample 2-7 and note ii.","text":"A proposed research test is to compare flight and ground runs at the component level. For a lunar question, match the flight-grade textile, overlap, oxygen, pressure and heat flux and measure whether flame spread continues after the heat source ends."},{"id":"saffire:decision","title":"Ferkul et al., Saffire-II composite results","url":"https://ntrs.nasa.gov/api/citations/20170008805/downloads/20170008805.pdf#page=25","locator":"PDF pp. 24–25, Table I p. 29, sample 2-7 and note ii.","text":"Assign combustion to the PMMA, damage to the Nomex, and no observed Nomex ignition in this test."},{"id":"flex:record","title":"NASA FLEX final report, positive case","url":"https://ntrs.nasa.gov/api/citations/20150023456/downloads/20150023456.pdf#page=189","locator":"PDF p. 189, printed p. 183, Fig. 159, FLEX-155.","text":"In FLEX-155, a free-floating heptane droplet burned in 18% O₂, 67% N₂ and 15% CO₂ at about 1 atm. Its initial/visible-extinction diameters were 2.73/2.52 mm. Subsequent high vaporization, a plateau and cloud formation led the investigators to infer cool-flame burning."},{"id":"flex:reason","title":"NASA FLEX final report, positive case","url":"https://ntrs.nasa.gov/api/citations/20150023456/downloads/20150023456.pdf#page=189","locator":"PDF p. 189, printed p. 183, Fig. 159, FLEX-155.","text":"The technical report interprets multiple time-resolved observations for each run. A visible endpoint in the experimental table refers to the hot luminous flame."},{"id":"flex:limit","title":"NASA FLEX final report, unresolved case","url":"https://ntrs.nasa.gov/api/citations/20150023456/downloads/20150023456.pdf#page=154","locator":"PDF p. 154, printed p. 148, Fig. 124, FLEX-120.","text":"FLEX-120 used a translated, fiber-supported droplet, 40% CO₂ and about 0.70 atm. The pair cannot isolate the effect of dilution. These are liquid heptane experiments in microgravity."},{"id":"flex:next","title":"NASA FLEX final report, positive case","url":"https://ntrs.nasa.gov/api/citations/20150023456/downloads/20150023456.pdf#page=189","locator":"PDF p. 189, printed p. 183, Fig. 159, FLEX-155.","text":"A proposed research test is to use synchronized droplet-size, optical and radiometric data with flagging for missing instruments. Compare matched initial diameters, diluent, support and pressure before estimating a suppression threshold."},{"id":"flex:decision","title":"NASA FLEX final report, positive case","url":"https://ntrs.nasa.gov/api/citations/20150023456/downloads/20150023456.pdf#page=189","locator":"PDF p. 189, printed p. 183, Fig. 159, FLEX-155.","text":"Retain an inferred cool-flame phase for FLEX-155 and unresolved cool-flame status for FLEX-120."},{"id":"same:record","title":"Meyer et al., spacecraft smoke detector performance","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7918997/#S8","locator":"Results §3.2 and Figure 9, left Shuttle, right ISS; dashed alarm thresholds.","text":"Meyer et al. compared signals from two detector technologies against alarm thresholds in SAME. The ISS light-scattering detector would have missed over half of the Kapton smoke tests and two-thirds of the Teflon tests. It responded strongly to several larger-particle smokes."},{"id":"same:reason","title":"Meyer et al., spacecraft smoke detector performance","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7918997/#S8","locator":"Results §3.2 and Figure 9, left Shuttle, right ISS; dashed alarm thresholds.","text":"Particles from overheated materials have different size distributions. The experiments measured the signal against defined thresholds, with no single response representing every material."},{"id":"same:limit","title":"Meyer et al., spacecraft smoke detector performance","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7918997/#S8","locator":"Results §3.2 and Figure 9, left Shuttle, right ISS; dashed alarm thresholds.","text":"The quoted fractions apply to the published test subsets, with no per-material denominator asserted here. The Shuttle ionization detector had fewer usable data. Dust, transport, filtration and layout matter to an installed detector. The commanded smoke-generation duration in PSI is not time to alarm."},{"id":"same:next","title":"Meyer et al., spacecraft smoke detector performance","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7918997/#S8","locator":"Results §3.2 and Figure 9, left Shuttle, right ISS; dashed alarm thresholds.","text":"A proposed research test is to select a sensor comparison with matched fuel, heating, flow and aerosol aging. Measure detection probability alongside nuisance alarms and transport delay under relevant ventilation."},{"id":"same:decision","title":"Meyer et al., spacecraft smoke detector performance","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7918997/#S8","locator":"Results §3.2 and Figure 9, left Shuttle, right ISS; dashed alarm thresholds.","text":"Judge performance by source material, detector type and threshold. Keep this finding separate from time to alarm in an occupied habitat."},{"id":"cfig:record","title":"Kimber, Spherical Gas-Fueled Cool Diffusion Flames","url":"https://api.drum.lib.umd.edu/server/api/core/bitstreams/278c77a3-6e86-4dc5-8413-c0381ebe74a9/content#page=62","locator":"PDF pp. 20–21 (printed pp. 9–10), Appendix E, Table E.6 on PDF p. 62 (printed p. 51), 21202A1–A2.","text":"CFI-G inverse tests 21202A1 and A2 used an 85% oxygen burner stream flowing into nitrogen with 6% ethane in the chamber. The dissertation tabulates nominal oxygen mass flows of 0.93 and 1.86 mg/s. A1 had no hot ignition. A2 ignited and self-extinguished after 2 seconds."},{"id":"cfig:reason","title":"Kimber, Spherical Gas-Fueled Cool Diffusion Flames","url":"https://api.drum.lib.umd.edu/server/api/core/bitstreams/278c77a3-6e86-4dc5-8413-c0381ebe74a9/content#page=62","locator":"PDF pp. 20–21 (printed pp. 9–10), Appendix E, Table E.6 on PDF p. 62 (printed p. 51), 21202A1–A2.","text":"The measurement location changes the physical meaning of the oxygen percentage. The investigators give the feed direction in Methods and tabulate the runs as inverse flames."},{"id":"cfig:limit","title":"NASA PSI, CFI-G experimental tables","url":"https://doi.org/10.60555/cyt1-kh64","locator":"PSI-159, inverse experimental table rows 18–19, header counted; normal and inverse tables label ambient and burner fields separately.","text":"The test matrix quotes nominal 2.0 atm. PSI has its own approximate initial pressure readings and unit labels. Use the value from the cited record in its stated units. Two consecutive trials alone cannot isolate a causal oxygen-flow effect."},{"id":"cfig:next","title":"NASA PSI, CFI-G experimental tables","url":"https://doi.org/10.60555/cyt1-kh64","locator":"PSI-159, inverse experimental table rows 18–19, header counted; normal and inverse tables label ambient and burner fields separately.","text":"A proposed research test is to compare matched normal and inverse configurations with explicit burner and chamber fields. For textile transfer, collect a separate solid-fuel record with measured ambient composition."},{"id":"cfig:decision","title":"Kimber, Spherical Gas-Fueled Cool Diffusion Flames","url":"https://api.drum.lib.umd.edu/server/api/core/bitstreams/278c77a3-6e86-4dc5-8413-c0381ebe74a9/content#page=62","locator":"PDF pp. 20–21 (printed pp. 9–10), Appendix E, Table E.6 on PDF p. 62 (printed p. 51), 21202A1–A2.","text":"Use these rows to study a gaseous inverse flame and the role of flow. Exclude their burner oxygen values from cabin-atmosphere and solid-fabric comparisons."},{"id":"ices:record","title":"Urban et al., ICES-2025-392, corrected captions","url":"https://ntrs.nasa.gov/api/citations/20250002114/downloads/ICES_2025-392-correctedcaptions.pdf#page=9","locator":"PDF pp. 6–11: Table 2 and Figs. 8 and 11. P213 result p. 9; opposite polycarbonate result p. 11.","text":"At 8.2 psia, Urban et al. found the lunar buoyant extinction limit for acrylic-adhesive P213 tape below the WSTF 1-g forced-flow extrapolation."},{"id":"ices:reason","title":"Urban et al., ICES-2025-392, corrected captions","url":"https://ntrs.nasa.gov/api/citations/20250002114/downloads/ICES_2025-392-correctedcaptions.pdf#page=9","locator":"PDF pp. 6–11: Table 2 and Figs. 8 and 11. P213 result p. 9; opposite polycarbonate result p. 11.","text":"The P213 comparison is explicitly against an extrapolated line. The polycarbonate passage compares against the WSTF data, with a proposed shift onto the quenching branch. Table 2 gives a separate conservative extrapolation for a possible correction."},{"id":"ices:limit","title":"Urban et al., local velocity and compensation model","url":"https://ntrs.nasa.gov/api/citations/20250002114/downloads/ICES_2025-392-correctedcaptions.pdf#page=10","locator":"PDF p. 10, section A, followed by Table 2 on p. 11.","text":"Both research facilities used a five-second extinction endpoint; NASA Test 1 uses five specimens and burn-length plus debris criteria. Ignition procedures differ between research rigs. The local lunar buoyant velocity was unknown. Table 2 values for P213 and polycarbonate (1.4 and 2.3 oxygen percentage points) describe the authors’ worst-case slope methodology, rather than measured shifts."},{"id":"ices:next","title":"Urban et al., ICES-2025-392, corrected captions","url":"https://ntrs.nasa.gov/api/citations/20250002114/downloads/ICES_2025-392-correctedcaptions.pdf#page=9","locator":"PDF pp. 6–11: Table 2 and Figs. 8 and 11. P213 result p. 9; opposite polycarbonate result p. 11.","text":"A proposed research test is to reproduce the material-specific comparison with a longer duration, measured local flow and the same matched ignition history. Keep signed observations separate from engineering margins."},{"id":"ices:decision","title":"Urban et al., ICES-2025-392, corrected captions","url":"https://ntrs.nasa.gov/api/citations/20250002114/downloads/ICES_2025-392-correctedcaptions.pdf#page=9","locator":"PDF pp. 6–11: Table 2 and Figs. 8 and 11. P213 result p. 9; opposite polycarbonate result p. 11.","text":"Keep a different conclusion for each material. Preserve the comparator named in each result."},{"id":"fm2:record","title":"Ferkul et al., FM² science requirements","url":"https://ntrs.nasa.gov/api/citations/20260001966/downloads/Ferkul-Lunar%20and%20Planetary%20Science%20Conf%202026%20v2.pdf#page=5","locator":"PDF pp. 5–6, 9–11, 14. Oxygen sequence and expected outcomes p. 5; Navy fabric and mounting p. 10.","text":"Ferkul et al. specify four separate 2 × 20 cm exposed Synergy Pro Navy fabric strips at 8.2 ± 0.3 psia, with initial oxygen of 37%, 33%, 29% and 25%. Their concept gives an expected lunar limiting oxygen concentration of 24–26%. They expect the first three tests to burn to threshold and the fourth not to ignite."},{"id":"fm2:reason","title":"Ferkul et al., FM² science requirements","url":"https://ntrs.nasa.gov/api/citations/20260001966/downloads/Ferkul-Lunar%20and%20Planetary%20Science%20Conf%202026%20v2.pdf#page=5","locator":"PDF pp. 5–6, 9–11, 14. Oxygen sequence and expected outcomes p. 5; Navy fabric and mounting p. 10.","text":"FM² refreshes the chamber between burns; oxygen can fall during a burn. Initial oxygen, successful ignition, post-igniter spread and oxygen at extinction are different measurements."},{"id":"fm2:limit","title":"Ferkul et al., FM² science requirements","url":"https://ntrs.nasa.gov/api/citations/20260001966/downloads/Ferkul-Lunar%20and%20Planetary%20Science%20Conf%202026%20v2.pdf#page=5","locator":"PDF pp. 5–6, 9–11, 14. Oxygen sequence and expected outcomes p. 5; Navy fabric and mounting p. 10.","text":"The reviewed sources are design and planning documents. No completed lunar outcomes are recorded. FIRST FIRE supplies a separately timestamped v1 team forecast. A deterministic limiting-oxygen model describes propagation conditional on establishment; a failed igniter, absent evidence or short observation must not become a scored negative."},{"id":"fm2:next","title":"Ferkul et al., FM² science requirements","url":"https://ntrs.nasa.gov/api/citations/20260001966/downloads/Ferkul-Lunar%20and%20Planetary%20Science%20Conf%202026%20v2.pdf#page=5","locator":"PDF pp. 5–6, 9–11, 14. Oxygen sequence and expected outcomes p. 5; Navy fabric and mounting p. 10.","text":"A proposed research test is to predefine each outcome, invalid-test handling, sensor requirements and scoring horizon. Preserve the forecast and its timestamp independently before using public outcome data."},{"id":"fm2:decision","title":"Ferkul et al., FM² science requirements","url":"https://ntrs.nasa.gov/api/citations/20260001966/downloads/Ferkul-Lunar%20and%20Planetary%20Science%20Conf%202026%20v2.pdf#page=5","locator":"PDF pp. 5–6, 9–11, 14. Oxygen sequence and expected outcomes p. 5; Navy fabric and mounting p. 10.","text":"Use the published qualitative expectation as a baseline. The fixed team forecast assumes a 26% mean and 1.5 percentage-point spread. Verify its signed timestamp and compare its probabilities with future resolved lunar burns."},{"id":"sibal:instrument","title":"Ferkul et al., LUCI flight and ground comparison","url":"https://ntrs.nasa.gov/api/citations/20250010653/downloads/ASGSR%202025-LUCI-Ferkul-Presentation-v2-20250010653.pdf#page=34","locator":"PDF pp. 4, 12, 16, 19, 23–27, 33–34, 42. Page 34 compares SIBAL flame width.","text":"LUCI compared SIBAL, a cotton–fiberglass composite fabric, burning downward in simulated lunar gravity with the same material at 1 g. SIBAL flame-base speed and flame-tip speed describe different moving boundaries. Time to visible extinction is a separate endpoint."},{"id":"saffire:time","title":"Ferkul et al., Saffire-II composite results","url":"https://ntrs.nasa.gov/api/citations/20170008805/downloads/20170008805.pdf#page=25","locator":"PDF pp. 24–25, Table I p. 29, sample 2-7 and note ii.","text":"In Saffire-II sample 2-7 the 140 s duration belongs to the composite test. The upstream PMMA (acrylic) burned. The downstream Nomex was damaged and blackened but did not ignite. Its reported burn length was zero."},{"id":"saffire:ground","title":"Thomsen, Berkeley dissertation, externally heated Nomex","url":"https://escholarship.org/uc/item/01d5j8mc","locator":"Chapter 6, experimental method and concurrent flame spread over HT90-40.","text":"Externally heated Nomex HT90-40 can burn under other conditions in 1-g experiments. The orbital sample 2-7 observation cannot certify Nomex as fireproof or safe in every atmosphere."},{"id":"flex:unresolved","title":"NASA FLEX final report, unresolved case","url":"https://ntrs.nasa.gov/api/citations/20150023456/downloads/20150023456.pdf#page=154","locator":"PDF p. 154, printed p. 148, Fig. 124, FLEX-120.","text":"In FLEX-120 (C12H201), a vapor cloud was observed but the ultraviolet instrument recorded no images. The authors judged the later cool-flame evidence inconclusive. Figure 124 does not give a confirmed second burning phase."},{"id":"flex:diagnostics","title":"NASA FLEX final report, positive case","url":"https://ntrs.nasa.gov/api/citations/20150023456/downloads/20150023456.pdf#page=189","locator":"PDF p. 189, printed p. 183, Fig. 159, FLEX-155.","text":"FLEX-155 (C03H201) burned visibly for 2.7 seconds. NASA's Figure 159 interprets later rapid droplet vaporization, a plateau and cloud formation as evidence of cool-flame burning. The visible flame's disappearance does not establish the time all combustion stopped."},{"id":"same:instrument","title":"Meyer et al., spacecraft smoke detector performance","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7918997/#S8","locator":"Results §3.2 and Figure 9, left Shuttle, right ISS; dashed alarm thresholds.","text":"The ISS light-scattering detector would have missed over half the Kapton smoke tests and about two-thirds of the Teflon tests in the reported subset. Those fractions describe crossings of that detector's alarm threshold. They do not predict a cabin alarm time or a general failure probability."},{"id":"same:smoke","title":"Meyer et al., spacecraft smoke detector performance","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7918997/#S8","locator":"Results §3.2 and Figure 9, left Shuttle, right ISS; dashed alarm thresholds.","text":"The SAME investigation heated spacecraft materials to generate smoke before ignition. Light-scattering and ionization detectors respond differently to aerosol size and material. A detector that responds to one smoke source can miss another."},{"id":"cfig:pressure","title":"NASA PSI, CFI-G experimental tables","url":"https://doi.org/10.60555/cyt1-kh64","locator":"PSI-159, inverse experimental table rows 18–19, header counted; normal and inverse tables label ambient and burner fields separately.","text":"Normal CFI-G run 21088A1 reported 39.39% initial ambient oxygen. Inverse runs 21202 A1 and A2 reported 85% oxygen in the burner stream, with 6% ethane in the chamber. PSI lists an approximate initial pressure of 2.2066 bar for the inverse pair. The source location and unit must stay with each value."},{"id":"cfig:flows","title":"NASA PSI, CFI-G experimental tables","url":"https://doi.org/10.60555/cyt1-kh64","locator":"PSI-159, inverse experimental table rows 18–19, header counted; normal and inverse tables label ambient and burner fields separately.","text":"CFI-G inverse PSI rows 18–19 report 0.931 and 1.862 mg/s oxygen flow. Run 21202 A1 had no hot ignition. A2 ignited and self-extinguished after 2 seconds (SE). Both used 85% oxygen in the burner. These two attempts alone cannot identify a causal flow threshold."},{"id":"ices:opposite","title":"Urban et al., higher polycarbonate and Nomex Velcro limit","url":"https://ntrs.nasa.gov/api/citations/20250002114/downloads/ICES_2025-392-correctedcaptions.pdf#page=11","locator":"PDF p. 11, first paragraph. Discussion refers to the WSTF data.","text":"At 8.2 psia P213 tape's lunar extinction oxygen limit was below its 1-g forced-flow extrapolation. Polycarbonate and Nomex Velcro had lunar limits above their WSTF ground measurements. The Earth comparator differs by material. A single oxygen correction cannot represent all three."},{"id":"ices:table","title":"Urban et al., local velocity and compensation model","url":"https://ntrs.nasa.gov/api/citations/20250002114/downloads/ICES_2025-392-correctedcaptions.pdf#page=10","locator":"PDF p. 10, section A, followed by Table 2 on p. 11.","text":"Table 2 gives conservative modeled oxygen adjustments of 1.4 percentage points for P213 and 2.3 for polycarbonate using a worst-case slope method. These are extrapolations. The investigators reported uncertainty about local buoyant velocity in simulated lunar gravity."},{"id":"ices:qualification","title":"NASA materials standard and active version","url":"https://standards.nasa.gov/standard/NASA/NASA-STD-6001","locator":"NASA-STD-6001B Change 3, §§7.1.2–7.1.4; PDF pp. 27–29.","text":"NASA-STD-6001B Change 3 Test 1 uses at least five specimens, burn length and flaming-debris criteria. The research apparatus used a five-second extinction criterion. A short research test does not establish material qualification for a crewed vehicle."},{"id":"fm2:date","title":"NASA FY 2027 budget request","url":"https://www.nasa.gov/wp-content/uploads/2026/04/fiscal-year-2027-full-budget-request.pdf","locator":"Planning reference, search the PDF for “Flammability of Materials on the Moon”.","text":"The April 2026 NASA FY 2027 budget request describes planned lunar FM² work in 2027. This review has no verified launch date or actual flight outcome. A budget year does not establish a launch commitment."},{"id":"fm2:probability","title":"FIRST FIRE · Reproduce the illustrative model","url":"#report/forecast","locator":"Reproduce the illustrative model","text":"The registered FIRST FIRE v1 shared-threshold forecast adopts a mean limiting oxygen of 26% with standard deviation 1.5 percentage points. Its probabilities of sustained spread are 37% O₂: >99.99%, 33% O₂: >99.99%, 29% O₂: 97.72%, 25% O₂: 25.25%. These are conditional model probabilities. NASA gave qualitative expectations and an expected 24–26% limit, without numerical probabilities."},{"id":"fm2:scoring","title":"FIRST FIRE · Reproduce the illustrative model","url":"#report/forecast","locator":"Reproduce the illustrative model","text":"A Brier score is the mean squared difference between the predicted probability and the observed binary outcome. Lower is better. Score only burns with resolved outcomes on the same indices and report coverage. Hypothetical yes/yes/yes/no gives 0.0161 for the model and 0.0100 for the guide's illustrative comparator. There are no observed FM² scores."},{"id":"fm2:event","title":"FIRST FIRE · One event per burn","url":"#report/forecast","locator":"One event per burn","text":"A scored yes means sustained flame spread after the igniter turns off. A nominal attempt with no ignition scores no. Hardware failure, invalid conditions, abort or unclassifiable observations are void. All four official outcomes in this release are pending. The learner guide's 90/10 numbers are an illustrative encoding of NASA's qualitative expectations."},{"id":"fm2:test","title":"FIRST FIRE · Choosing the next oxygen test","url":"#report/forecast","locator":"Choosing the next oxygen test","text":"The four modeled tests share a latent limiting oxygen concentration. Their outcomes are dependent. With no outcomes, the most informative next oxygen setting on the candidate grid is 26%, the median assumed threshold. Four burns cannot establish calibration across materials or habitats."},{"id":"evaluation:design","title":"FIRST FIRE · A practical six-case pilot","url":"#report/evaluation","locator":"A practical six-case pilot","text":"The planned blind study compares FIRST FIRE with ordinary search under equal time limits across six independent, previously unpublished prompts. The facilitator assigns each participant three cases per method. Independent assessors grade decision, primary evidence with a locator, and scope. Practice tasks are excluded. No human performance advantage has been established."},{"id":"evaluation:search","title":"FIRST FIRE · Public retrieval benchmark","url":"#report/search","locator":"Public retrieval benchmark","text":"On 18 authored retrieval queries, hybrid semantic plus keyword search and keyword-only search both placed the intended case first 15 times and in the top three 17 times. Those public-case results measure retrieval. Human decision quality has not been measured."},{"id":"archive:coverage","title":"FIRST FIRE · NASA PSI data audit","url":"#report/data","locator":"NASA PSI data audit","text":"The frozen NASA Physical Sciences Informatics (PSI) snapshot contains 1,058 normalized observation rows from 9 investigations, with 19 investigations in its catalog and 20 original CSV tables. The other ten studies remain catalog-only. Every normalized observation is from orbital microgravity. It includes no direct lunar-surface measurements."},{"id":"archive:provenance","title":"FIRST FIRE · Measuring conditions and endpoints","url":"#report/data","locator":"Measuring conditions and endpoints","text":"Each normalized record retains the original NASA accession, versioned source URL, CSV record number (header counts as 1), DOI and original file identifier. The data explorer exposes the original CSV row. Missing values stay blank and are not replaced with zero. Nominal zero gravity labels orbital microgravity rather than an accelerometer measurement."},{"id":"archive:rank","title":"FIRST FIRE · Measuring conditions and endpoints","url":"#report/data","locator":"Measuring conditions and endpoints","text":"Habitat ranking compares material or subject, nominal gravity, ambient oxygen and absolute pressure. Rows with more reported conditions rank before less complete rows, followed by weighted distance. Inverse burner oxygen is excluded from atmospheric matching. The nearest orbital record still requires a transfer check for material, shape, airflow and endpoint."},{"id":"psi-10:catalog","title":"Advanced Combustion via Microgravity Experiments / Flame Design","url":"https://doi.org/10.60555/w4zy-bt45","locator":"PSI-10 investigation catalog and experimental table","text":"Flame Design (PSI-10). Advanced Combustion via Microgravity Experiments / Flame Design. Varies gas composition, pressure and flow to study soot in normal and inverse flames. This release has 0 normalized rows. Two raw test tables. The PSI license field is empty. See the dataset for reuse terms."},{"id":"psi-20:catalog","title":"Advanced Combustion via Microgravity Experiments - Burning Rate Emulator","url":"https://doi.org/10.60555/vb93-3y72","locator":"PSI-20 investigation catalog and experimental table","text":"BRE (PSI-20). Advanced Combustion via Microgravity Experiments - Burning Rate Emulator. Uses a gas burner to emulate different solid fuels in quiet surroundings. This release has 0 normalized rows. Raw table groups several oxygen levels and ignitions into each day."},{"id":"psi-21:catalog","title":"Advanced Combustion via Microgravity Experiments / Coflow Laminar Diffusion Flame","url":"https://doi.org/10.60555/23e1-9950","locator":"PSI-21 investigation catalog and experimental table","text":"CLD Flame (PSI-21). Advanced Combustion via Microgravity Experiments / Coflow Laminar Diffusion Flame. Examines the structure and stability of gas diffusion flames across fuel dilution levels. This release has 0 normalized rows. Raw table summarizes test days and ranges."},{"id":"psi-22:catalog","title":"Advanced Combustion via Microgravity Experiments Electric-Field Effects on Laminar Diffusion Flames","url":"https://doi.org/10.60555/se5a-8c73","locator":"PSI-22 investigation catalog and experimental table","text":"E-FIELD Flames (PSI-22). Advanced Combustion via Microgravity Experiments Electric-Field Effects on Laminar Diffusion Flames. Applies electric fields to change flame flow and shape in microgravity. This release has 0 normalized rows. Raw table summarizes test days. Electrical forcing supplies an analogy to gravity."},{"id":"psi-23:catalog","title":"Advanced Combustion via Microgravity Experiments-Structure and Response of Spherical Diffusion Flames","url":"https://doi.org/10.60555/k57n-p030","locator":"PSI-23 investigation catalog and experimental table","text":"s-Flame (PSI-23). Advanced Combustion via Microgravity Experiments-Structure and Response of Spherical Diffusion Flames. Studies transport and chemical reactions in spherical diffusion flames. This release has 0 normalized rows. Raw table summarizes test days and gas mixtures."},{"id":"psi-25:catalog","title":"Burning and Suppression of Solids - II","url":"https://doi.org/10.60555/4qc4-de67","locator":"PSI-25 investigation catalog and experimental table","text":"BASS-II (PSI-25). Burning and Suppression of Solids - II. Examines ignition, spread and extinction of solids in low-speed forced flow. This release has 129 normalized rows. Initial and final oxygen are distinct. Table records fan and air displays without a velocity calibration or sustained-burning outcome."},{"id":"psi-26:catalog","title":"Burning and Suppression of Solids","url":"https://doi.org/10.60555/58h4-dy80","locator":"PSI-26 investigation catalog and experimental table","text":"BASS (PSI-26). Burning and Suppression of Solids. Examines solid fuels of different shapes and thicknesses in forced flow. This release has 121 normalized rows. One maintenance row excluded. Repeated as-run numbers distinguished by their planned-test numbers."},{"id":"psi-39:catalog","title":"Cool Flames Investigation","url":"https://doi.org/10.60555/m6pj-a914","locator":"PSI-39 investigation catalog and experimental table","text":"CFI (PSI-39). Cool Flames Investigation. Studies cool flames in liquid hydrocarbon droplets as pressure and dilution vary. This release has 79 normalized rows. Eight exact repeated records removed. Composition and pressure are available; a cool-flame outcome per row is unavailable."},{"id":"psi-68:catalog","title":"Flame Extinguishment Experiment - 2","url":"https://doi.org/10.60555/byp8-h018","locator":"PSI-68 investigation catalog and experimental table","text":"FLEX-2 (PSI-68). Flame Extinguishment Experiment - 2. Extends droplet experiments to fuel mixtures and weak imposed convection. This release has 0 normalized rows. Raw CSV gives ranges and candidate levels by fuel. Individual realized combinations are unavailable in this table."},{"id":"psi-69:catalog","title":"Flame Extinguishment Experiment","url":"https://doi.org/10.60555/mbq8-0451","locator":"PSI-69 investigation catalog and experimental table","text":"FLEX (PSI-69). Flame Extinguishment Experiment. Measures droplet burning and visible extinction in controlled oxygen and diluent mixtures. This release has 274 normalized rows. Visible extinction, disruption and completion remain separate. Consult the experiment report for post-visible behavior."},{"id":"psi-98:catalog","title":"Spacecraft Fire Safety Experiment-I","url":"https://doi.org/10.60555/0t15-1z43","locator":"PSI-98 investigation catalog and experimental table","text":"Saffire-I (PSI-98). Spacecraft Fire Safety Experiment-I. Examines large cotton-fiberglass fabric in concurrent and opposed airflow in an uncrewed Cygnus vehicle. This release has 2 normalized rows. Two burns used the same specimen. Excludes camera and pre-flow records."},{"id":"psi-99:catalog","title":"Spacecraft Fire Experiment-II","url":"https://doi.org/10.60555/2chp-m469","locator":"PSI-99 investigation catalog and experimental table","text":"Saffire-II (PSI-99). Spacecraft Fire Experiment-II. Compares spacecraft materials and flame spread directions in an uncrewed cargo vehicle. This release has 9 normalized rows. Nine sample records. Oxygen is derived from carbon dioxide production and the initial ISS measurement."},{"id":"psi-100:catalog","title":"Spacecraft Fire Experiment-III","url":"https://doi.org/10.60555/040q-4h36","locator":"PSI-100 investigation catalog and experimental table","text":"Saffire-III (PSI-100). Spacecraft Fire Experiment-III. Studies concurrent and opposed flow around large cotton-fiberglass fabric at 30 cm/s. This release has 2 normalized rows. The experimental CSV omits pressure, oxygen and endpoint."},{"id":"psi-101:catalog","title":"Smoke Aerosol Measurement Experiment-Reflight","url":"https://doi.org/10.60555/2np7-jv14","locator":"PSI-101 investigation catalog and experimental table","text":"SAME-R (PSI-101). Smoke Aerosol Measurement Experiment-Reflight. Varies material heating, smoke transport and aging to characterize aerosols for detection. This release has 109 normalized rows. Inlet velocity refers to the smoke source. Rows include aged observations. Test 57 is listed for two materials."},{"id":"psi-102:catalog","title":"Smoke and Aerosol Measurement Experiment","url":"https://doi.org/10.60555/gd4k-8h62","locator":"PSI-102 investigation catalog and experimental table","text":"SAME (PSI-102). Smoke and Aerosol Measurement Experiment. Studies aerosol growth from heated spacecraft materials under different flow and aging conditions. This release has 0 normalized rows. Raw table lists settings and grouped materials. It supplies no alarm times or individual alarm trials."},{"id":"psi-106:catalog","title":"Structure and Liftoff In Combustion Experiment","url":"https://doi.org/10.60555/pm12-rg61","locator":"PSI-106 investigation catalog and experimental table","text":"SLICE (PSI-106). Structure and Liftoff In Combustion Experiment. Examines the structure, stability and liftoff of a gas diffusion flame. This release has 0 normalized rows. Raw table groups fuels and calibration work by test day."},{"id":"psi-107:catalog","title":"Smoke Point In Co-flow Experiment","url":"https://doi.org/10.60555/9kbh-e962","locator":"PSI-107 investigation catalog and experimental table","text":"SPICE (PSI-107). Smoke Point In Co-flow Experiment. Varies fuel and air delivery around gas jets to study their onset of soot emission. This release has 0 normalized rows. Settings can repeat within one ignition. The raw table is available without promoting rows to separate burns."},{"id":"psi-115:catalog","title":"Utilization of the Smoke Aerosol Measurement Experiment Data for Advanced Modeling and Simulation of Smoke Generation in Micro-Gravity","url":"https://doi.org/10.60555/q0v5-1v28","locator":"PSI-115 investigation catalog and experimental table","text":"SAME smoke modeling (PSI-115). Utilization of the Smoke Aerosol Measurement Experiment Data for Advanced Modeling and Simulation of Smoke Generation in Micro-Gravity. Uses smoke measurements to model aerosol transport and growth under different gravity conditions. This release has 0 normalized rows. Ground simulation using SAME data. PSI lists no experimental CSV for this record."},{"id":"psi-159:catalog","title":"Advanced Combustion via Microgravity Experiments / Cool Flames Investigation with Gases","url":"https://doi.org/10.60555/cyt1-kh64","locator":"PSI-159 investigation catalog and experimental table","text":"CFI-G (PSI-159). Advanced Combustion via Microgravity Experiments / Cool Flames Investigation with Gases. Studies normal and inverse gas diffusion flames with a spherical burner. This release has 333 normalized rows. Normal oxygen is in the chamber. Inverse oxygen is in the burner stream. Ignition and termination are separate fields."},{"id":"acrylic:rod","title":"Link et al., The Effect of Gravity on Flame Spread over PMMA Cylinders","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5760683/#Fig8","locator":"Figure 8(a–c), oxygen and rod diameter","text":"For the 9.53 and 12.7 mm cast black PMMA rods near 21% oxygen, the measured Earth spread rates were higher than in orbit under these flow conditions. The 6.35 mm orbital series extends only to about 19% oxygen. At roughly 17.5% oxygen, all three diameters spread in orbit. Earth flames did not spread below 19% in this comparison without added radiation. Buoyancy changes the local opposed flow."},{"id":"acrylic:panel","title":"Opposed Flame Spreading Along a Structured PMMA Sample","url":"https://ntrs.nasa.gov/citations/20210017785","locator":"Figs. 6–9, 14–15, specimen, ignition and edge speeds","text":"Saffire V tested a ribbed PMMA panel at 26.9% oxygen and 76.1 kPa in orbit. The flames advanced along rib edges. The observed downstream ignition was preceded by an upstream attempt with apparent loss of igniter contact. These observations cannot supply a rod spread speed, a panel ignition probability or a general cabin safety rating."},{"id":"apollo1:overview-1","title":"NASA · Apollo 1","url":"https://www.nasa.gov/mission/apollo-1/","locator":"Mission overview, Crew and Apollo Pad Fire","text":"On January 27, 1967, a fire swept through Apollo 1’s command module during a countdown rehearsal at Launch Complex 34 in Cape Kennedy, Florida. The spacecraft was still on the ground. All three astronauts died: Gus Grissom, Ed White and Roger Chaffee."},{"id":"apollo1:overview-2","title":"Apollo 204 Review Board report","url":"https://www.nasa.gov/missions/apollo/apollo-1/report-of-the-apollo-204-review-board/","locator":"Fire chronology and Board findings on ignition, cabin atmosphere and crew escape","text":"The cabin’s pressurized pure oxygen and flammable materials let the fire spread rapidly. Rising pressure held the inward-opening hatch shut. Investigators considered an electrical arc the most likely ignition source, but could not identify exactly what started the fire."},{"id":"apollo1:crew-1","title":"NASA · Apollo 1","url":"https://www.nasa.gov/mission/apollo-1/","locator":"Mission overview, Crew and Apollo Pad Fire","text":"Gus Grissom, Ed White and Roger Chaffee were inside Apollo 1. All three died in the fire during the ground test on January 27, 1967."},{"id":"apollo1:cause-1","title":"Apollo 204 Review Board report","url":"https://www.nasa.gov/missions/apollo/apollo-1/report-of-the-apollo-204-review-board/","locator":"Fire chronology and Board findings on ignition, cabin atmosphere and crew escape","text":"The Apollo 204 Review Board identified an electrical arc as the most likely ignition source. Several wires showed evidence of arcing, but the board could not establish which one, if any, started the fire. Once flames took hold, combustible cabin materials burned rapidly in the pressurized pure oxygen."},{"id":"apollo1:escape-1","title":"Apollo 204 Review Board report","url":"https://www.nasa.gov/missions/apollo/apollo-1/report-of-the-apollo-204-review-board/","locator":"Fire chronology and Board findings on ignition, cabin atmosphere and crew escape","text":"Apollo 1’s inner hatch opened inward. As the fire heated the cabin gas, pressure inside rose and held the hatch shut. Smoke and heat slowed the pad crew as they removed the hatches from outside. They reached the astronauts about five minutes after the first fire call, too late to save them."},{"id":"apollo1:changes-1","title":"NASA History · The Apollo 1 fire and its aftermath","url":"https://www.nasa.gov/history/55-years-ago-the-apollo-1-fire-and-its-aftermath/","locator":"Investigation and changes to the Apollo command module","text":"After Apollo 1, engineers gave the command module a single hatch that opened outward quickly, protected wiring bundles and removed or replaced flammable cabin materials. NASA also introduced more flame-resistant spacesuits."},{"id":"apollo1:atmosphere-1","title":"Apollo 204 Review Board report","url":"https://www.nasa.gov/missions/apollo/apollo-1/report-of-the-apollo-204-review-board/","locator":"Fire chronology and Board findings on ignition, cabin atmosphere and crew escape","text":"During the Apollo 1 ground test, the sealed cabin held 100% oxygen at 16.7 psia (pounds per square inch absolute). Those conditions allowed combustible cabin materials to burn rapidly once ignited."},{"id":"apollo1:setting-1","title":"NASA · Apollo 1","url":"https://www.nasa.gov/mission/apollo-1/","locator":"Mission overview, Crew and Apollo Pad Fire","text":"The Apollo 1 fire happened on January 27, 1967, during a preflight ground test at Launch Complex 34 in Cape Kennedy, Florida. The rocket had not launched."},{"id":"apollo1:comparison-1","title":"NASA · Apollo 1","url":"https://www.nasa.gov/mission/apollo-1/","locator":"Mission overview, Crew and Apollo Pad Fire","text":"Apollo 1 was a ground-test cabin fire on January 27, 1967. All three astronauts died."},{"id":"apollo13:overview-1","title":"NASA · Mission Control, Houston, April 13, 1970","url":"https://www.nasa.gov/image-article/mission-control-houston-april-13-1970/","locator":"Service module oxygen tank failure and crew response","text":"On April 13, 1970, an oxygen tank exploded in Apollo 13’s service module while the crew was on its way to the Moon. The crew abandoned the landing and used the lunar module as a shelter for the return flight."},{"id":"apollo13:overview-2","title":"NASA · Apollo 13","url":"https://www.nasa.gov/mission/apollo-13/","locator":"Crew, mission overview and return to Earth","text":"Jim Lovell, Jack Swigert and Fred Haise all returned alive, splashing down in the Pacific on April 17."},{"id":"apollo13:crew-1","title":"NASA · Apollo 13","url":"https://www.nasa.gov/mission/apollo-13/","locator":"Crew, mission overview and return to Earth","text":"Apollo 13 carried Jim Lovell, Jack Swigert and Fred Haise. All three survived and returned to Earth on April 17, 1970."},{"id":"apollo13:cause-1","title":"NASA · Mission Control, Houston, April 13, 1970","url":"https://www.nasa.gov/image-article/mission-control-houston-april-13-1970/","locator":"Service module oxygen tank failure and crew response","text":"An electrical fault in one of Apollo 13’s service module oxygen tanks led to an explosion. The spacecraft lost its normal oxygen and electrical supplies. The crew shut down the command module and used the lunar module to sustain them on the way home."},{"id":"apollo13:escape-1","title":"NASA · Mission Control, Houston, April 13, 1970","url":"https://www.nasa.gov/image-article/mission-control-houston-april-13-1970/","locator":"Service module oxygen tank failure and crew response","text":"The Apollo 13 crew shut down the command module to conserve its batteries and moved into the lunar module for the trip home. They used the command module again for reentry and all three survived."},{"id":"apollo13:setting-1","title":"NASA · Mission Control, Houston, April 13, 1970","url":"https://www.nasa.gov/image-article/mission-control-houston-april-13-1970/","locator":"Service module oxygen tank failure and crew response","text":"Apollo 13’s oxygen tank exploded on April 13, 1970, in the service module as the spacecraft was traveling toward the Moon."},{"id":"apollo13:comparison-1","title":"NASA · Apollo 13","url":"https://www.nasa.gov/mission/apollo-13/","locator":"Crew, mission overview and return to Earth","text":"Apollo 13 suffered an oxygen tank explosion during the trip to the Moon in April 1970. Its three astronauts made it home."},{"id":"sibal:review14","title":"FIRST FIRE research review","url":"#report/review","locator":"Experiments and counterevidence · LUCI","text":"1. LUCI, slower spread and a longer-lived SIBAL flame. In the New Shepard flight a 5 × 30 cm cotton–fiberglass strip burned downward, while a 4 mm PMMA rod burned upward. The apparatus rotated and both samples used the same atmosphere. For SIBAL, the paired ground/partial-g comparisons report flame-base speeds of 1.5/0.9 mm/s and flame-tip speeds of 2.8/1.1 mm/s. The flame-width comparison reports extinction roughly 45 seconds earlier on Earth. The individual flight fit gives 0.92 mm/s for the base and the comparison table rounds to 0.9. The rocket carried the experiment in a sealed chamber in simulated lunar gravity. The deck’s total burn duration across the experiment is a poor substitute for a specific fabric’s duration."},{"id":"sibal:review16","title":"FIRST FIRE research review","url":"#report/review","locator":"Experiments and counterevidence · LUCI","text":"LUCI’s ground comparison tracked a near-20% oxygen atmosphere during the SIBAL observation. In flight, concentration declined from roughly 20% to 18%. The investigators also describe less reliable ground tracking. These features preclude a universal duration multiplier or a claim that only gravity changed. An independent 20-second parabolic test of downward-spreading, 5-cm-wide SIBAL at 21% oxygen and normal pressure measured 0.86 mm/s base speed. A short centrifuge-drop experiment gave 1.1 mm/s. They strengthen the *early spread* comparison; their time windows cannot test a 45-second difference in extinction. An earlier poster describes immediate Earth extinction under its own conditions; use the actual paired LUCI run to answer the numerical duration question."},{"id":"saffire:review18","title":"FIRST FIRE research review","url":"#report/review","locator":"Experiments and counterevidence · Saffire","text":"2. Saffire-II, what ignited at a material interface. Sample 2-7 used a 5-cm PMMA lead-in and 24-cm length of Nomex HT90-40 with about 7 mm overlap. The PSI table lists approximately 22.1% oxygen, 20 cm/s concurrent flow, 80 W igniter power, 9.2 s igniter time and 140 s composite burn duration. Its phase-specific result is 5 cm PMMA consumed and zero Nomex burn length. NASA also describes significant damage to the first centimetre and blackening over the first five. Soot deposition is one possible explanation for discoloration. The assembly’s elapsed time cannot serve as either a Nomex ignition delay or a Nomex burn duration. Ground experiments with the same grade found that PMMA could support Nomex burning in ambient air until the external flame burned out. Rank support for the exact composite event separately from support for assisted or self-sustained Nomex spread in a changed atmosphere."},{"id":"flex:review20","title":"FIRST FIRE research review","url":"#report/review","locator":"Experiments and counterevidence · FLEX","text":"3. FLEX, visible extinction and later chemistry. NASA’s PSI row 156 records a 2.73 mm initial droplet, 2.52 mm diameter at visible extinction and 2.7 s burn time for FLEX-155. The technical report interprets the subsequent high vaporization rate, plateau and vapor cloud as evidence of cool combustion. Keep “investigators inferred” attached to that conclusion. FLEX-120 also produced a cloud, but incomplete diagnostics left cool burning inconclusive. Its row 121 records initial/visible-extinction diameters of 2.45/2.39 mm. The changed pressure, support and CO₂ fraction prevent treating these two runs as a controlled estimate of CO₂ suppression efficacy. A project that uses the same exact-quote checker for both captions must still make opposite decisions about evidence strength."},{"id":"same:review22","title":"FIRST FIRE research review","url":"#report/review","locator":"Experiments and counterevidence · SAME","text":"4. SAME, measured smoke and the likelihood of an alarm. In §3.2 of their original study, Meyer and colleagues compare sensor responses against a dashed alarm threshold in Figure 9. The ISS light-scattering unit would have missed over half the tested Kapton cases and two-thirds of the Teflon cases. The same detector produced large responses to several other smokes. The Shuttle detector had fewer usable observations. Preserve each fraction exactly at the authors’ level of reporting: there is no basis here for a per-material denominator extrapolated from the total number of runs. In the PSI reflight table, runs 51 and 101 both list 60 s at the source but differ in inlet flow, heater setting and net aging. Their 60 s is a generation setting. The experiment does not supply a time-to-alarm for a lunar cabin."},{"id":"same:review24","title":"FIRST FIRE research review","url":"#report/review","locator":"Experiments and counterevidence · SAME","text":"The original §3.2 says over half for Kapton. A later NASA white paper summarizes that as half. The original authors’ result controls the case answer, and the later paper supplies context about deposition, filtration and design. A separate exact join is possible for SAME-R Teflon run 56 (CSV row 74: 8.1 cm/s inlet, 60 s smoke generation, 41 s net aging). Figure 10(a) explicitly shows an *unaged* Teflon subsample from that run. It documents particle morphology; the source offers no run-56 alarm classification in that figure. Recent detector work treats discrimination between smoke, cabin dust and lunar dust as a separate design objective and studies transport to sensors."},{"id":"cfig:review26","title":"FIRST FIRE research review","url":"#report/review","locator":"Experiments and counterevidence · CFI-G","text":"5. CFI-G, physical location of a gas measurement. In the inverse configuration the chamber contains diluted fuel and oxidizer issues from a porous sphere. The 21202A1 and A2 rows both have 6% initial ambient ethane and 85% oxygen in the burner stream. The dissertation gives nominal oxygen mass flows of 0.93 and 1.86 mg/s. Only A2 recorded hot ignition, for two seconds before self-extinction. The original PSI table records approximate pressure of 2.2066 bar in both rows, while Appendix E of the dissertation reports nominal 2.0 atm. Direct conversion of 2.0 atm yields 2.0265 bar: the two values are different reported quantities. Keep the original field and qualifier with each value. Assigning the 85% to a habitat-atmosphere slider would promote a gas-burner test above a solid sample on a false match."},{"id":"ices:review28","title":"FIRST FIRE research review","url":"#report/review","locator":"Experiments and counterevidence · ICES","text":"6. ICES-2025-392, test protocol, specimen and comparator. Urban et al. changed conditions after ignition: the Glenn centrifuge group lowered local oxygen and the WSTF rig increased flow. Both used whether a flame survived a five-second window. At 8.2 psia the P213 tape result lies below WSTF’s forced-flow extrapolation. For polycarbonate and Nomex Velcro the paper describes lunar limits higher than the WSTF data. Preserve the wording of the comparator. P213 combines fiberglass with acrylic adhesive. Nomex Velcro has a different thickness and form from woven Nomex used in other studies. The authors discuss a possible shift onto the quenching branch and consider the relevant lunar buoyant velocity unknown. Their plotted positions do not constitute velocity measurements. Table 2 reports conservative differences obtained by extrapolating a worst-case slope from an assumed 35 cm/s at 1 g to zero; these are different from the observed lunar-minus-Earth differences. A separate study compared thin polycarbonate and Nomex under opposed flow in microgravity; its extrema occur under different flow and gravity. Transfer requires matching the comparison as well as the material."},{"id":"fm2:review30","title":"FIRST FIRE research review","url":"#report/review","locator":"Experiments and counterevidence · FM²","text":"7. FM², prediction with four dependent trials. The March 2026 design supersedes a 2024 configuration involving two different fuels. On viewer p. 10 it specifies Synergy Pro Navy; the older shortlist table on viewer p. 14 calls one candidate Natural Synergy Pro. Confirm grade, finish and lot before joining a comparison. With a nominally common limiting oxygen concentration for the four specimens, outcomes are dependent and the effective sample size is small. A Brier score can compare predictions on resolved indices. It cannot establish calibration from one four-burn mission. NASA gives qualitative expectations and a 24–26% expected LOC. The guide's 26%/1.5 percentage-point distribution is a teaching assumption. A shared oxygen threshold assumes that sufficient starting oxygen will produce sustained spread after a functioning igniter. Registering a separate ignition model would be necessary to estimate a distinct ignition-failure probability. A nominal attempt with no ignition and an invalid igniter have different scoring dispositions. A changed design or missing footage can also make an observation unscorable. The April FY 2027 budget request plans FM² lunar work for 2027. These documents provide the design and planning basis; an official result with traceable per-burn outcomes is still needed for scoring."},{"id":"archive:data-18","title":"FIRST FIRE · NASA PSI data audit","url":"#report/data","locator":"Measuring conditions and endpoints · source line 18","text":"record_id is accession, table number and CSV record number joined by colons. CSV numbering counts the header as 1. source_file, source_row, source_url and doi preserve the trace to the original. The raw manifest pins each file version. Whitespace and source spellings remain in originals. A blank normalized field means unavailable, inapplicable or rejected with a displayed reason. A recorded zero is distinct from a blank. Derived values carry up to eight decimal places for comparison and do not imply additional instrumental precision."},{"id":"archive:data-20","title":"FIRST FIRE · NASA PSI data audit","url":"#report/data","locator":"Measuring conditions and endpoints · source line 20","text":"Oxygen columns distinguish initial ambient gas, final ambient gas and oxidizer delivered through a burner. o2_low_pct and o2_high_pct preserve a reported ambient interval for Saffire or duplicate the initial ambient value for the other studies. A Saffire single approximate value is accompanied by its qualifier. Initial/final concentrations in BASS-II and normal CFI-G are temporally distinct measurements."},{"id":"archive:data-21","title":"FIRST FIRE · NASA PSI data audit","url":"#report/data","locator":"Measuring conditions and endpoints · source line 21","text":"Absolute pressures use 760 mmHg = 1 atm = 101.325 kPa ≈ 14.69595 psia. PSI-69 record C11M201 contains zero pressure and reports burning. Its derived pressure is blank and its source value is retained. Circumstances and undocumented uncertainty can prevent a precise comparison even when pressure is reported."},{"id":"archive:data-22","title":"FIRST FIRE · NASA PSI data audit","url":"#report/data","locator":"Measuring conditions and endpoints · source line 22","text":"Orbital microgravity is coded as nominal zero g for broad scenario comparisons. No row-level accelerometer values were derived. The accessible PSI flight tables give no real lunar gravity observation here."},{"id":"archive:data-23","title":"FIRST FIRE · NASA PSI data audit","url":"#report/data","locator":"Measuring conditions and endpoints · source line 23","text":"Flow in cm/s uses explicitly dimensioned source values. BASS-II fan displays, ACME mass flow and optical camera frame counts remain distinct from airflow velocity. A SAME-R inlet velocity describes smoke generation, not the airflow over a spreading flame."},{"id":"archive:data-24","title":"FIRST FIRE · NASA PSI data audit","url":"#report/data","locator":"Measuring conditions and endpoints · source line 24","text":"phase describes the tested fuel or detection phenomenon. SAME-R uses aerosol; fuel phase alone is insufficient to compare fire behavior across materials. The Saffire CSV sample detail gives thickness × length × width in the listed order. A missing material name is never filled through a guess based on the previous row."},{"id":"archive:data-25","title":"FIRST FIRE · NASA PSI data audit","url":"#report/data","locator":"Measuring conditions and endpoints · source line 25","text":"burn_time_s, hot_ignition, termination_code, an actual natural extinction time, and a smoke heating duration are different measurements. CFI-G's FT denotes stopping the flow, SE denotes self-extinction. Only explicit burn times become numeric, with a qualifier when the source gives an approximation."},{"id":"archive:data-26","title":"FIRST FIRE · NASA PSI data audit","url":"#report/data","locator":"Measuring conditions and endpoints · source line 26","text":"The FLEX CSV column headings drop gas-name subscripts and label the burning-rate unit as mm. The experimental report's Table IX identifies O₂, CO₂, N₂ and rate in mm²/s. Gas species mappings use that report. We leave the disputed rate unit out of the normalized table. Some source compositions do not sum to one; no missing fraction is redistributed. The technical report discusses possible contamination for the disruptive tests in section 6."},{"id":"archive:data-30","title":"FIRST FIRE · NASA PSI data audit","url":"#report/data","locator":"Consequential counterexamples · source line 30","text":"Visible extinction. FLEX-155 (C03H201; PSI-69 CSV row 156) used heptane at 764.9 mmHg in an 18% O₂, 67% N₂, 15% CO₂ chamber on the ISS. The droplet began at 2.73 mm and measured 2.52 mm at visible extinction. The CSV reports 2.7 s and an extinction endpoint. The investigator's Figure 159 (printed p.183) describes fast vaporization continuing afterward, an eventual plateau and a vapor cloud, evidence for cool-flame burning after visible loss. Figure 124 for C12H201/FLEX-120 describes an inconclusive post-visible observation despite a vapor cloud. Both rows say “Extinction.” A row-level endpoint lookup alone cannot classify a cool flame. The two documents trace the same experiment."},{"id":"archive:data-32","title":"FIRST FIRE · NASA PSI data audit","url":"#report/data","locator":"Consequential counterexamples · source line 32","text":"Joining trials. PSI-69 CSV row 157 assigns C03H401 to number 156. The NASA report's Table IX assigns that same identifier and timestamp to FLEX-157. Use the engineering identifier, time, fuel and conditions to cross-check joins, preserve the native IDs for both sources, and mark dubious matches for review."},{"id":"archive:data-34","title":"FIRST FIRE · NASA PSI data audit","url":"#report/data","locator":"Consequential counterexamples · source line 34","text":"Burner versus habitat. In CFI-G inverse CSV rows 18–19, 21202 A1 and A2 share 85% oxygen in the burner stream, 6% initial ethane in the chamber and a source pressure labeled approximately 2.2066 bar. The first records no hot ignition at 0.931 mg/s O₂. The second records hot ignition, 2 seconds and SE at 1.862 mg/s. This pair cannot determine a unique ignition threshold. The thesis labels the condition 2.0 atm; retain the two reported pressure values rather than forcing agreement. Compare normal CSV row 2, 21088A1, with measured pre-test chamber oxygen of 39.39%. All are gas tests. At a 34% cutoff, naively pooling inlet and ambient oxygen adds 106 false chamber matches to 113 legitimate initial chamber rows in these tables. 79 inverse rows use the 85% burner stream. Initial O₂ alone does not make the normal gas rows directly applicable to fabric in lunar gravity."},{"id":"archive:data-36","title":"FIRST FIRE · NASA PSI data audit","url":"#report/data","locator":"Consequential counterexamples · source line 36","text":"Initial oxygen and exposure duration. BASS-II T28b (row 129) starts at 20.7% and records 40.4% at the end. Its paired T28a records 0.9% final oxygen. A start-of-test filter cannot take either final as the initial exposure. BASS-II's initial range is 13.6–22.2% across 129 records. Saffire I row 2 records 420 s until operators switched the flow off; the opposed burn reused the remaining fabric. Comparing durations as two independent extinction observations confounds procedure, fuel history and direction."},{"id":"archive:data-38","title":"FIRST FIRE · NASA PSI data audit","url":"#report/data","locator":"Consequential counterexamples · source line 38","text":"Beyond the selected PSI tables. Saffire VI-2 burned 50 cm SIBAL fabric at 31.0% O₂, 54.1 kPa and 20 cm/s in orbit. Its paper provides a substantially closer atmospheric analogue to a nominal 34%/8.2 psia exploration atmosphere than Saffire I's approximately 21.5% O₂ burn. A transfer claim still needs matching fuel, geometry, flow and gravity. This published result has a different provenance from the 1,058 PSI observations."},{"id":"fm2:forecast-16","title":"FIRST FIRE · FM²: a forecast that can be wrong","url":"#report/forecast","locator":"One event per burn · source line 16","text":"The scoring question is whether the fabric sustains flame propagation after the hot-wire igniter switches off. A nominal attempt that never ignites counts as no. A momentary flash without sustained spread also counts as no. Actual outcome classification requires an attributable flight report, sample identity, conditions and a clear statement of what happened. Keep a changed or aborted protocol, faulty igniter/sensor, or unclassifiable event void. Ground tests, simulations, launch animations, and weakly glowing hot wire do not resolve the question. Retain missing data as pending. A separate observation, extinction oxygen, requires a sustained burn that reaches a measured extinction point and a valid oxygen reading there. A sample exhausted or extinguished on command cannot supply that endpoint."},{"id":"fm2:forecast-18","title":"FIRST FIRE · FM²: a forecast that can be wrong","url":"#report/forecast","locator":"One event per burn · source line 18","text":"The fourth NASA expectation is specifically about ignition. The FIRST FIRE event is sustained spread, which implies ignition. For burns 1–3 NASA envisages propagation until the atmosphere reaches the limiting oxygen level. A high starting oxygen and finite sample might still yield burnout before a threshold can be measured. The model does not simulate igniter heat transfer, oxygen depletion, thermal transients, fabric-to-fabric differences, or operational faults."},{"id":"fm2:forecast-22","title":"FIRST FIRE · FM²: a forecast that can be wrong","url":"#report/forecast","locator":"Reproduce the illustrative model · source line 22","text":"Let one uncertain effective threshold L have a normal distribution with mean 26% oxygen and standard deviation 1.5 percentage points. For a nominal burn starting at x, the model assumes propagation exactly when x > L. P(sustained spread) is the normal cumulative probability at (x−26)/1.5. The central 80% model interval for L is 24.08–27.92%. These are the learner guide's B8.3 worked assumptions. NASA gives an expected 24–26% lunar limiting-oxygen range, without a probability density or standard deviation. The project probabilities were specified before lunar results. The separately retained v1 file and signed timestamp appear below."},{"id":"fm2:forecast-31","title":"FIRST FIRE · FM²: a forecast that can be wrong","url":"#report/forecast","locator":"Reproduce the illustrative model · source line 31","text":"The learner guide’s B8.4 worked example uses 90/10 for an illustrative “NASA-style” comparator. The researchers give qualitative expectations only; the fixed v1 forecast explicitly records that comparator. The same four targets were used when selecting the assumptions, so agreement with NASA's expectations is not a validation test. Moving the mean from 24 to 27 with the same 1.5-point spread moves the burn-4 probability from 74.75% to 9.12%. Other materials behave differently in simulated lunar tests; they provide physical motivation, not Synergy Pro calibration."},{"id":"fm2:forecast-33","title":"FIRST FIRE · FM²: a forecast that can be wrong","url":"#report/forecast","locator":"Reproduce the illustrative model · source line 33","text":"Under the Brier score, smaller is better. Average (predicted probability − binary observed outcome)² across the same resolved burns for both predictors, and give the coverage. The full score requires all four. With hypothetical outcomes yes/yes/yes/no, the model scores 0.0161 and the comparator 0.0100. With yes/yes/yes/yes, they score 0.1398 and 0.2100. Neither is an observed result. Four tests with a common material and shared threshold do not establish population calibration, even when results eventually arrive."},{"id":"fm2:forecast-35","title":"FIRST FIRE · FM²: a forecast that can be wrong","url":"#report/forecast","locator":"Reproduce the illustrative model · source line 35","text":"For one hypothetical repeat, choose a starting O₂ value on a 22–30% grid in 0.5-point steps, keeping everything else fixed. With a noiseless threshold observation, binary entropy is the expected information about L. At the default mean, 26% yields an even split and 1 bit. For two simultaneous design choices x<y, the three possible patterns have probabilities F(x), F(y)−F(x), and 1−F(y). The grid maximum is 25.5% and 26.5% with 1.567 bits of joint information. Counting the two single-test entropies separately double-counts shared information. These are proposed extra conditions under the model. If the goal changes to qualifying a material, or ignition has independent variability, the design criterion changes."},{"id":"fm2:forecast-45","title":"FIRST FIRE · FM²: a forecast that can be wrong","url":"#report/forecast","locator":"Reproduce the illustrative model · source line 45","text":"Only the default invocation writes data/forecast.json. Alternate assumptions and score examples print to standard output. The fixed has a dated 14 November 2026 at 12:57:06 UTC. Its SHA-256 is 9f565bc7195936bde5faff67841c5e1e6537581bc4fc560018838fbf996a8fa3. A DOI has not been issued. The four reference travel estimates are 20, 17.5, 7.5 and 0 cm, using a linear eight-percentage-point oxygen decrease per full 20 cm sample at the mean threshold. Score future binary outcomes using the frozen probabilities."},{"id":"fm2:forecast-49","title":"FIRST FIRE · FM²: a forecast that can be wrong","url":"#report/forecast","locator":"How uncertain is the travel estimate? · source line 49","text":"At 25% initial oxygen, a strip travels 0 cm if its threshold is exactly 26%. A lower threshold can allow spread. In this unregistered extension we average travel over the same normal distribution used for sustained spread. For each possible threshold, the length ranges from zero to the full 20 cm strip. It increases by 2.5 cm per oxygen percentage point between those limits. The team chose this linear depletion law for the scenario. The flight design provides the specimen geometry and an estimate of chamber oxygen depletion."},{"id":"fm2:forecast-58","title":"FIRST FIRE · FM²: a forecast that can be wrong","url":"#report/forecast","locator":"How uncertain is the travel estimate? · source line 58","text":"To reproduce the calculation, let H(x) = (x − μ) Φ(z) + σ φ(z), where z = (x − μ)/σ, Φ is the standard normal cumulative distribution and φ is its density. H is the expected positive excess of starting oxygen x above the threshold. The mean clipped travel is 2.5 × [H(x) − H(x − 8)] cm. Dividing by the probability of sustained spread gives the last column, since the remaining thresholds contribute zero travel. The numerical test compares the formula with direct integration of the clipped length against the normal density."},{"id":"fm2:forecast-60","title":"FIRST FIRE · FM²: a forecast that can be wrong","url":"#report/forecast","locator":"How uncertain is the travel estimate? · source line 60","text":"The table varies the assumed threshold alone. Testing this distance law requires measured travel after igniter cutoff, together with oxygen readings and the reason spread stopped. The signed file specifies how to evaluate its original point estimates. The exploratory averages shown here have no registered scoring role."},{"id":"methods:advanced-methods-7","title":"FIRST FIRE · From a NASA observation to a testable decision","url":"#report/advanced-methods","locator":"Match before revealing the outcomes · source line 7","text":"The matched experiment tool restricts its comparison to a single FLEX fuel. Choose oxygen or pressure as the exposure, select two settings and constrain the other conditions, including droplet diameter and diluent composition. The algorithm pairs distinct rows using conditions known before the outcome. It first maximizes the number of pairs and then minimizes their total matching cost. Review the sample IDs, controls and tolerances before revealing the results. A locked protocol can still lose all its pairs when a stricter condition is applied."},{"id":"methods:advanced-methods-9","title":"FIRST FIRE · From a NASA observation to a testable decision","url":"#report/advanced-methods","locator":"Match before revealing the outcomes · source line 9","text":"At the default methanol settings, the 15% and 21% oxygen groups at a target 14.7 psia give three pairs. Their higher-minus-lower oxygen burn durations differ by −4.8, −3.3 and +12.9 seconds. Their average is +1.6 seconds. Requiring the same experimental day removes all three pairs. Repeated tests can share hardware, and burn durations can end through different mechanisms. Selecting by a predicted outcome would favor experiments that confirmed the prediction."},{"id":"methods:advanced-methods-13","title":"FIRST FIRE · From a NASA observation to a testable decision","url":"#report/advanced-methods","locator":"Model a remote tracer sensor · source line 13","text":"The transport simulator represents two connected volumes at uniform concentration. Let A and B be the tracer masses in mg and Vₐ and Vᵦ the volumes in m³. Concentrations are A/Vₐ and B/Vᵦ. A source injects a constant mass per second during a finite pulse. A symmetric volumetric exchange Q transfers Q(A/Vₐ − B/Vᵦ) mg/s from A to B. A clean-air flow F into the remote zone exhausts F B/Vᵦ mg/s. A first-order sensor approaches the local concentration with time constant τ. At τ = 0 it follows that concentration instantly. The plot shows a five-minute run and the first crossing of the selected threshold. Inputs, units, mass balance, time series and limits are included with every download."},{"id":"methods:advanced-methods-15","title":"FIRST FIRE · From a NASA observation to a testable decision","url":"#report/advanced-methods","locator":"Model a remote tracer sensor · source line 15","text":"The solver steps the mass balance every 0.1 seconds and integrates the sensor response exponentially over each step. Its tests check an analytic pulse response, zero exchange, nonnegative masses, conservation and refinement to 0.05 seconds. It models an inert tracer. Ignition, heat transport, buoyancy, aerosol deposition and detector calibration need independent measurements. Two-zone tracer fitting has a published basis."},{"id":"methods:advanced-methods-17","title":"FIRST FIRE · From a NASA observation to a testable decision","url":"#report/advanced-methods","locator":"Model a remote tracer sensor · source line 17","text":"The separate measured-repeat panel uses the four whole-room mixing times from Um et al. In the higher-flow, neutral-air setting the two runs took 174 and 206 seconds. In the lower-flow, heated-air setting they took 451 and 532 seconds. The room volume was 158 m³, the release lasted 20 seconds and the authors used a spatial relative standard deviation threshold of 20%. We approximate the sensor array with two equal sealed volumes. For inverse time constant λ = 4Q/V and pulse length d, the relative zone contrast at the end of the pulse is (1−exp(−λd))/(λd). It then decays exponentially. We fit λ using one reported time per setting, retain the setting and predict the other run. The absolute errors are 32 and 81 seconds. Copying the calibration time gives the same errors. Two repeat pairs test repeatability and cannot validate full concentration traces, sensor delay or spacecraft transfer."},{"id":"methods:advanced-methods-19","title":"FIRST FIRE · From a NASA observation to a testable decision","url":"#report/advanced-methods","locator":"Model a remote tracer sensor · source line 19","text":"For timestamped concentration data, upload two run files to the trace fitter. Choose known conditions for each, fit on the first, then inspect residuals on the second alongside an independently fitted one-zone baseline. Keep the synthetic demonstration separate from measured data."},{"id":"methods:advanced-methods-23","title":"FIRST FIRE · From a NASA observation to a testable decision","url":"#report/advanced-methods","locator":"Choose the next experiment · source line 23","text":"The FM² Design Lab represents a single uncertain limiting oxygen percentage on a grid with 0.05-percentage-point bins. A burn sustains above this common limit. The likelihood includes a user-selected probability of recording the opposite binary outcome. Each hypothetical reading updates the weights. The calculation evaluates each reachable oxygen setting and, with two specimens, each possible second decision after the first reading. One objective maximizes expected information on the shared limit. The other reduces expected squared probability error for a selected planned burn. A contradictory sequence at zero reading error requires an explicit edit to the assumptions or readings."},{"id":"methods:advanced-methods-25","title":"FIRST FIRE · From a NASA observation to a testable decision","url":"#report/advanced-methods","locator":"Choose the next experiment · source line 25","text":"At the defaults, two specimens with 5% reading error give an expected information gain of about 1.426 bits. The first setting is 26% oxygen. A sustained reading moves the next recommended setting to 25%; a negative reading moves it to 27%. These are model expectations under the stated assumptions. The separately signed four-burn forecast keeps its original probabilities and scoring protocol."},{"id":"physics-lab:master-physics-7","title":"FIRST FIRE · Cabin fire dynamics","url":"#report/master-physics","locator":"Sealed cabin, atmosphere and crew · source line 7","text":"For volume V at 300 K, initial gas moles are PV/(RT). In a closed chamber a repeat unit CₐHᵦO𝒸 consumes a+b/4−c/2 O₂ molecules, producing a CO₂ and b/2 H₂O. The front advances at the prescribed speed until its strip, combustible mass allowance or oxygen limit is exhausted. Extinction ends that fire for the remainder of the run. The two-minute default consumes 72 g cellulose, moves 36 cm, releases 1,094.4 kJ, and ends at 32.753% O₂ and 0.972% CO₂. The original strip balance gives the same result. The oxygen-concentration cutoff and prescribed speed are scenario inputs."},{"id":"physics-lab:master-physics-9","title":"FIRST FIRE · Cabin fire dynamics","url":"#report/master-physics","locator":"Sealed cabin, atmosphere and crew · source line 9","text":"The metabolic model uses NASA activity-specific O₂ consumption and CO₂ production in grams per person per minute. Sleep uses 0.37/0.44, nominal duty 0.59/0.69, and aerobic work 3.99/5.22. The scrubber removes CO₂ up to its flow and cumulative sorbent capacity. Oxygen make-up starts half a specified tolerance below setpoint, adds toward the target and respects its own rate and tank capacity. Breathing stops consuming oxygen that is unavailable, and the returned oxygen shortfall marks that boundary. The controller operates on oxygen fraction. A physiological atmosphere assessment would also need inspired partial pressures, accumulated contaminants and biomedical criteria."},{"id":"physics-lab:master-physics-11","title":"FIRST FIRE · Cabin fire dynamics","url":"#report/master-physics","locator":"Sealed cabin, atmosphere and crew · source line 11","text":"The 24-hour test uses a rigid 12 m³ cabin at 101.325 kPa, starting at 21% O₂, with two nominal crew, oxygen and scrubber capacities of 4 kg and 5 kg, and processing capacities of 3 and 4 g/min. Oxygen remains between 20.9000% and 21.0000% in a target band of 20.8–21.2%. Crew consume 1,699.2 g O₂ and produce 1,987.2 g CO₂. The sample interval in the downloadable trace is coarser than the controller step. The acceptance range uses every integration step. Switching off support or reducing tank capacity exposes supply exhaustion."},{"id":"physics-lab:master-physics-13","title":"FIRST FIRE · Cabin fire dynamics","url":"#report/master-physics","locator":"Sealed cabin, atmosphere and crew · source line 13","text":"For a dry initial atmosphere, oxygen partial pressure is total pressure times oxygen fraction. At 101.3 kPa/21%, it is 21.27 kPa. At 56.5 kPa/34%, it is 19.21 kPa. The nitrogen partial-pressure-to-suit-pressure ratio for a 29.6 kPa suit falls from about 2.70 to 1.26 across those scenarios. That ratio is a comparison aid. An EVA prebreathe procedure requires mission-specific physiological evidence. The same starting oxygen partial pressure can coexist with different oxygen fractions, total pressures and material fire behavior."},{"id":"physics-lab:master-physics-17","title":"FIRST FIRE · Cabin fire dynamics","url":"#report/master-physics","locator":"Heat, pressure and remote sensing · source line 17","text":"The gas sensible energy above a 300 K reference is the sum of species moles times constant molar heat capacities at fixed volume times the temperature rise. N₂, O₂, CO₂ and water vapor use 20.8, 21.0, 28.8 and 25.3 J/(mol·K). The optional He and Ar diluents use 1.5R. The model adds net chemical heat, crew heat and battery deposition, with battery energy and cutoff time enforced. Extracted gases carry their modeled sensible energy. It applies an exponential wall exchange step with fixed wall temperature and heat-transfer conductance. Pressure follows nRT/V. The residual is the difference between energy added and the sum of energy stored, exported with gas and transferred to walls. It checks numerical bookkeeping. Gas temperatures also depend on the assumed deposited fraction, wall properties, spatial mixing, and the omitted condensation and heat capacity variation."},{"id":"physics-lab:master-physics-19","title":"FIRST FIRE · Cabin fire dynamics","url":"#report/master-physics","locator":"Heat, pressure and remote sensing · source line 19","text":"With no wall loss, the imposed energy stays in the modeled cabin except for extracted gas. The browser uses 1 s steps for an active front and 15 s for long no-fire runs. A 24-hour fixed-wall result does not include transient wall storage, routing heat into equipment, or local flame temperature. The end time, fuel and heat inputs apply to the particular trajectory."},{"id":"physics-lab:master-physics-21","title":"FIRST FIRE · Cabin fire dynamics","url":"#report/master-physics","locator":"Heat, pressure and remote sensing · source line 21","text":"The separate two-compartment solver now accepts an initial remote concentration. For a closed connection between compartments, initial remote tracer of 20 mg/m³, 8 m³ remote volume and 15 L/s of clean air, its remote signal decays as 20 exp(−0.015t/8). At 300 s forward stepping at 0.2 s gives 11.39445 mg/m³, against the analytic 11.39566. The largest relative error is 0.01055%. The sensor experiment supports calibration and evaluation on separate uploaded traces."},{"id":"physics-lab:master-physics-25","title":"FIRST FIRE · Cabin fire dynamics","url":"#report/master-physics","locator":"Dissociating equilibrium and thermal spread · source line 25","text":"Cantera 3.2.0 computes gas-phase equilibrium at fixed enthalpy and pressure for 53 GRI-Mech 3.0 species. The solid does not appear in GRI-Mech. For one fuel repeat unit we form complete CO₂/H₂O/N₂ products at 300 K with the correct elemental inventory, add the fuel's net heat of combustion to their reference enthalpy, then re-equilibrate those products at HP. This permits dissociation into species such as CO, H₂ and radicals while retaining the specified bulk heat input. This is an adiabatic flame-zone estimate for stoichiometric oxygen/nitrogen oxidizer, independent of inert-helium and argon cabin cases. It omits pyrolysis kinetics, soot, local mixture fraction and heat loss."},{"id":"physics-lab:master-physics-27","title":"FIRST FIRE · Cabin fire dynamics","url":"#report/master-physics","locator":"Dissociating equilibrium and thermal spread · source line 27","text":"The lookup ships 84 temperatures spanning two fuels, oxygen from 10% to 40%, and pressure from 30 to 110 kPa. Bilinear interpolation at ten off-grid conditions agrees within 0.835% of direct equilibrium calls, below the 2% acceptance tolerance. The table includes the species file's SHA-256. Fresh off-grid solves check interpolation accuracy; they supply no flight measurements. Regenerate using Python with cantera==3.2.0 and python scripts/build_master_equilibrium.py."},{"id":"physics-lab:master-physics-31","title":"FIRST FIRE · Cabin fire dynamics","url":"#report/master-physics","locator":"Helium and argon cabin comparisons · source line 31","text":"The Atmosphere designer uses separate dissociating-equilibrium tables for helium and argon. It adds neutral He from Cantera’s NASA gas thermochemistry file to the 53 GRI-Mech species, including Ar. For each inert gas and fuel, the calculation replaces nitrogen with that diluent mole for mole. It uses the same fuel net heat and 300 K reference as the nitrogen solver. Helium and argon have nearly equal molar heat capacities across this neutral-gas model, so their temperatures at equal oxygen mole fraction and pressure are often identical to the published precision. Their molar masses differ, which changes the predicted mass of cabin gas. A temperature estimate is local to the idealized flame zone. Measured specimen spread, heat loss and gas ionization require additional models or evidence."},{"id":"physics-lab:master-physics-33","title":"FIRST FIRE · Cabin fire dynamics","url":"#report/master-physics","locator":"Helium and argon cabin comparisons · source line 33","text":"Acceptance passed. Both fuels at seven oxygen fractions and six pressures give 168 temperatures rounded to 0.001 K. At five other oxygen–pressure pairs for each fuel and diluent, 20 direct Cantera solves check the browser’s bilinear interpolation. The maximum relative error was 1.78481% against a 2% limit. It occurred for polyethylene at 12.2% oxygen and 35.1 kPa in both gases. A direct solve gave 2,098.122 K. The browser withholds estimates outside 10–40% oxygen or 30–110 kPa. This comparison measures interpolation error against the thermochemical solver. It supplies no measured flame-temperature validation."},{"id":"physics-lab:master-physics-35","title":"FIRST FIRE · Cabin fire dynamics","url":"#report/master-physics","locator":"Helium and argon cabin comparisons · source line 35","text":"With Python and cantera==3.2.0, run the following from the repository root. The verifier checks the SHA-256 of both source YAML files, reproduces all shipped nodes, checks the 20 independently recomputed references against their published test values, and enforces the interpolation tolerance. The optional --inert-report FILE.json argument saves the complete grids, direct temperatures and errors. The default command without flags continues to regenerate the nitrogen Physics Lab table."},{"id":"physics-lab:master-physics-44","title":"FIRST FIRE · Cabin fire dynamics","url":"#report/master-physics","locator":"Helium and argon cabin comparisons · source line 44","text":"For the master document's full-thickness thin-fuel convention, speed in m/s is (π/4)·k_g/(ρₛ cₛ d)·(T_f−T_v)/(T_v−T∞). NASA reports SIBAL fabric near 0.32 mm with area density 0.182 kg/m². This gives 573 kg/m³ for 0.3175 mm. The nominal heat capacity of 1,350 J/(kg·K), pyrolysis temperature of 600 K and emissivity of 0.8 are engineering assumptions. Cantera gives 0.04578 W/(m·K) for 21/79 O₂/N₂ at 600 K. The default conditional speed is 0.738 mm/s. Under NASA's radiative-extinction scaling a low-flow screening velocity is εσ(Tᵥ⁴−T∞⁴)/[ρ_g c_pg (T_f−Tᵥ)], using the local pressure, ideal-gas density at Tᵥ and assumed gas heat capacity of 1,050 J/(kg·K). At the default conditions this is 0.592 cm/s. Quenching, blowoff and unknown regime selections withhold the speed. An observed blowoff boundary requires flow and kinetics data."},{"id":"physics-lab:master-physics-46","title":"FIRST FIRE · Cabin fire dynamics","url":"#report/master-physics","locator":"Helium and argon cabin comparisons · source line 46","text":"The opposed Saffire-I run used approximately 21.5% oxygen and 20 cm/s airflow. The conditional prediction is 0.748 mm/s against 1.3 mm/s. Fitting that one record gives a multiplier of 1.739. At 21.6% oxygen, the midpoint of the concurrent record, the fitted prediction becomes 1.303 mm/s against the measured 1.8 mm/s. Both calculations assume 101.325 kPa. These two directions reuse one specimen, and the formula omits directional and thermal-history effects. The raw estimate meets the roadmap's factor-of-ten scale test. Holding one direction out reveals a 0.497 mm/s miss even after calibration. No oxygen limit or lunar front speed follows from this comparison."},{"id":"physics-lab:master-physics-50","title":"FIRST FIRE · Cabin fire dynamics","url":"#report/master-physics","locator":"Recurrent surrogate release decision · source line 50","text":"Two local PyTorch models trained on 640 exact sealed-strip runs with 60 steps at 2 s intervals. A separate 96-run validation set selects the best epoch. The untouched 160-run test set yields 9,600 errors. The 24-state liquid cell learns its input and recurrent weights through a positive, input-dependent decay rate. A 24-state tanh RNN trains on the same features, runs, optimizer, epoch budget and target. Both estimates use the same physical clipping at the oxygen cutoff. A nearest-training-trajectory baseline averages the four nearest normalized scenarios. The stronger table uses two known fuel stoichiometries, 17 initial oxygen values and 37 consumed-oxygen fractions. It bilinearly interpolates before applying the cutoff. Knowledge of the equations makes this a demanding and relevant comparator."},{"id":"physics-lab:master-physics-59","title":"FIRST FIRE · Cabin fire dynamics","url":"#report/master-physics","locator":"Recurrent surrogate release decision · source line 59","text":"The release rule requires the trained liquid candidate to beat the structured lookup on held-out mean absolute oxygen error. The candidate was dropped. These metrics measure imitation of the equations. They do not establish validity against measured cabin fires. Reproduce with CPU PyTorch 2.6, NumPy, Node, and python scripts/train_master_surrogate.py. The JS fixture generator calls the existing exact solver, splits by entire run and records the seeds. The signed lunar forecast is independent of these experiments."},{"id":"physics-lab:master-physics-63","title":"FIRST FIRE · Cabin fire dynamics","url":"#report/master-physics","locator":"Independent FDS fire cases · source line 63","text":"NIST FDS 6.11.1 ran three offline calculations on an Apple-silicon native build of the tagged source. Each run used one MPI rank and one OpenMP thread. The two sealed cubic chambers have 8 m³ of dry air at 101.325 kPa and 300 K, Earth gravity, a 0.25 m² floor burner, and inert enclosing walls. Each methane pulse ramps from zero to the specified heat-release density over 2 s, holds until 20 s, returns to zero by 22 s, and finishes at 45 s. The low and high burners use 50 and 100 kW/m². The high burner also runs with 24³ rather than 16³ mesh cells. The stored device output is the volume mean of oxygen mole fraction at each solver-reported sample time. All three .out summaries report successful completion."},{"id":"physics-lab:master-physics-65","title":"FIRST FIRE · Cabin fire dynamics","url":"#report/master-physics","locator":"Independent FDS fire cases · source line 65","text":"The comparator integrates the *prescribed* burner curve using 50,000 kJ/kg methane and 0.016043 kg/mol, independently of FDS's realized heat-release output. One mole of methane supplied at the surface consumes two moles of oxygen and contributes a net one mole of gas to the enclosure when water remains vapor. The predicted oxygen fraction is (x₀n₀−2ξ)/(n₀+ξ). The calculation uses the FDS device's starting oxygen fraction, 0.20954574, and no subsequent oxygen readings. Comparison is on the 46 reported timestamps for each case."},{"id":"physics-lab:master-physics-73","title":"FIRST FIRE · Cabin fire dynamics","url":"#report/master-physics","locator":"Independent FDS fire cases · source line 73","text":"Each maximum is below the chosen 0.25-point tolerance. With oxygen held constant, the maximum error would be 0.213 and 0.425 points on the original coarse cases. The weak-fire constant baseline also passes that absolute tolerance. The coarse-to-fine final value moves 0.001679 points. These three cases test imposed fuel consumption and cabin-average inventory. Small prescribed burners bypass solid pyrolysis. They supply no lunar flame-spread result, measured cabin validation or evidence of local detector performance."},{"id":"physics-lab:master-physics-75","title":"FIRST FIRE · Cabin fire dynamics","url":"#report/master-physics","locator":"Independent FDS fire cases · source line 75","text":"The repository stores three FDS input decks, original device and heat-release CSVs, and completion metadata in data/master-physics/fds/. The browser download includes their SHA-256 hashes, decks, paired traces, actual heat-release rates and errors. Run python scripts/check_master_fds.py to recalculate the comparison from the archived files. With a local executable, python scripts/check_master_fds.py --fds /absolute/path/to/fds reruns each deck in an isolated directory before computing the comparison. This release used GNU Fortran 16, Open MPI 5.0.11 and the official FDS-6.11.1 source tarball with SHA-256 f0a3493ea5f77b18ee5aae065ffb5c3677ae5cc0e1479b5aac22872b472dc417. The release was built from Build/ompi_gnu_osx with make -j6 -f ../makefile ompi_gnu_osx VPATH=../../Source COMP_FC=mpifort LFLAGS=."},{"id":"imaging:video-measurement-7","title":"FIRST FIRE · A Saffire-I flame measurement from five flight frames","url":"#report/video-measurement","locator":"Clock and image geometry · source line 7","text":"Each date-like number in the first column below is the suffix of an archived filename. Using the suffix, join each mapped photograph to its ICMAD companion. The text NASA added beneath that companion gives the original name, camera acquisition count, exposure and gain. All five exposures are 30,000 microseconds at 0 dB gain. Urban and colleagues report that the cameras acquired 30 frames per second. Subtract acquisition count 1047 and divide by 30 to get elapsed time. The filenames differ by 13,998 milliseconds over the selected span, consistent with the 14.0 seconds from the independent counter and nominal camera cadence. Dropped and unselected frames still count toward elapsed time."},{"id":"imaging:video-measurement-17","title":"FIRST FIRE · A Saffire-I flame measurement from five flight frames","url":"#report/video-measurement","locator":"Clock and image geometry · source line 17","text":"NASA’s mapped camera-2 photographs are 1,705 × 1,222 pixels. The downloadable 30 mm checkerboard is a pre-flight camera-2 calibration target. Its mapped JPEG also measures 1,705 × 1,222. The annotations use a separate, 1,280-pixel-wide image plus a footer. Use the mapped JPEG for a coordinate and the annotated image for the count. The archived readme explains the distortion correction and the distinction between flight frames and pre-flow."},{"id":"imaging:video-measurement-21","title":"FIRST FIRE · A Saffire-I flame measurement from five flight frames","url":"#report/video-measurement","locator":"Reproduce the worked measurement · source line 21","text":"The endpoint here is the projected position of the bright red band. The window’s origin is the top-left corner of the decoded native JPEG. For each x, average red minus blue over y = 350 through 850 inclusive. Smooth this profile with a horizontal, centered seven-pixel moving average. Within x = 250 through 650 inclusive, find the rightmost pixel at or above half that frame’s maximum. Measuring relative to the local peak accommodates a fading signal. A stronger or weaker luminous feature, a different field of view or a different band can shift the endpoint."},{"id":"imaging:video-measurement-23","title":"FIRST FIRE · A Saffire-I flame measurement from five flight frames","url":"#report/video-measurement","locator":"Reproduce the worked measurement · source line 23","text":"The contour moves 49 px in 14.0 s, or 3.50 px/s toward increasing x. Moving the threshold to 40% gives 3.57 px/s, and 60% gives 3.50 px/s. This is sensitivity to one choice of threshold. A manually placed point may differ. This contour describes emitted light projected onto the image. Converting the value into fuel-surface propagation would also require a defined physical front and its relation to the observed light."},{"id":"imaging:video-measurement-25","title":"FIRST FIRE · A Saffire-I flame measurement from five flight frames","url":"#report/video-measurement","locator":"Reproduce the worked measurement · source line 25","text":"With Python, Pillow and NumPy installed, run this from the repository root to verify each photo against its digest and recompute the result."},{"id":"imaging:video-measurement-55","title":"FIRST FIRE · A Saffire-I flame measurement from five flight frames","url":"#report/video-measurement","locator":"What would support a physical speed? · source line 55","text":"Obtain a camera-2 calibration that ties the target plane to the measured specimen plane, with the same lens, ROI offsets and distortion map as these frames. Use a local multi-square fit around the measurement band, quantify residual distortion and perspective, and propagate their uncertainty. The record lists PSI-98_Raw Data_SAFFIRE-I_ImageFrameSizes_ROI_Offsets_Grid_1280x920_v1.0.pdf. Its public download returned HTTP 404 during this audit. The checkerboard spacing and matching output dimensions alone leave plane registration unresolved. The example therefore retains pixels and seconds. The published spread speeds remain independent measurements."},{"id":"imaging:video-measurement-57","title":"FIRST FIRE · A Saffire-I flame measurement from five flight frames","url":"#report/video-measurement","locator":"What would support a physical speed? · source line 57","text":"The downloadable manifest records the three NASA ZIP names and hashes, each original member name and its SHA-256, nominal camera cadence, individual source counts and the worked contour settings. PSI lists the dataset under CC0 1.0. The five science JPEGs and their five corresponding annotated JPEGs were copied byte for byte after ZIP member CRC validation."},{"id":"transport:transport-fit-13","title":"FIRST FIRE · Fit a sensor trace","url":"#report/transport-fit","locator":"What the model estimates · source line 13","text":"With constant equal-volume exchange in both directions, tracer flow from the source to the sensor compartment equals the exchange rate times the difference between their concentrations. Clean ventilation removes tracer from the sensor volume. A first-order sensor follows the remote concentration with time constant τ. Both compartments and the sensor start at zero excess concentration. The status of a smoke alarm is outside this passive-tracer model."},{"id":"transport:transport-fit-15","title":"FIRST FIRE · Fit a sensor trace","url":"#report/transport-fit","locator":"What the model estimates · source line 15","text":"The fitting routine searches exchange from 0 to 800 L/s and τ from 0 to 60 s. A coarse grid followed by smaller local steps minimizes calibration root mean squared error (RMSE), weighting each recorded reading equally. Irregular sampling gives denser periods greater weight. The predictor integrates at 0.2 s, stores one-second samples and linearly interpolates to observation times. A competing single-compartment model instantly mixes the same mass throughout the combined volume, uses the same clean-air supply and calibrates its own τ on a 0.5 s grid."},{"id":"transport:transport-fit-17","title":"FIRST FIRE · Fit a sensor trace","url":"#report/transport-fit","locator":"What the model estimates · source line 17","text":"The held-out readings enter only after the two fits. RMSE penalizes large misses, mean absolute error reports typical absolute error, and signed bias is prediction minus observation. Compare the residual curves for delayed arrivals or late departures even if the average error is small. The held-out run tests transfer to these conditions. Generalization needs independently repeated runs at other relevant settings."},{"id":"transport:transport-fit-21","title":"FIRST FIRE · Fit a sensor trace","url":"#report/transport-fit","locator":"Read the synthetic example · source line 21","text":"Both examples use a 4 m³ source, an 8 m³ sensor compartment, 15 L/s of clean air, 38 L/s exchange and an 11 s sensor response. Calibration releases 0.50 g over 20 s. The held-out run releases 0.75 g over 32 s. The generator integrates at 0.05 s, samples every 5 s and adds two deterministic sinusoidal perturbations with different phases between runs. Each CSV contains 61 readings. These data were generated for checking the implementation."},{"id":"transport:transport-fit-29","title":"FIRST FIRE · Fit a sensor trace","url":"#report/transport-fit","locator":"Read the synthetic example · source line 29","text":"The fit recovers 38 L/s and 11 s. The single-compartment fit reaches its allowed sensor-lag maximum of 60 s. At the default 0.15 mg/m³ allowance, 72 of 358 examined two-parameter settings fall within that much RMSE of the best setting. Their exchange rates span 36.5–39.25 L/s and their sensor times span 9–12.5 s. The JSON records actual joint settings at each extreme. These ranges describe the sampled grid and chosen tolerance. They carry no statistical confidence level. An isolated chamber illustrates why this matters. When tracer cannot reach the sensor, the entire tested lag range can fit the zero signal."},{"id":"transport:transport-fit-31","title":"FIRST FIRE · Fit a sensor trace","url":"#report/transport-fit","locator":"Read the synthetic example · source line 31","text":"The separate measured-repeat panel in Transport Lab uses published room mixing times. Its endpoint summaries cannot supply the sensor-concentration CSVs needed here."},{"id":"world-model:world-model-15","title":"FIRST FIRE · The sealed-cabin model and its next validation experiment","url":"#report/world-model","locator":"Compare the model with the Saffire-I record · source line 15","text":"Reverse the flow pairs the two Saffire-I runs with a controlled sensitivity test. In PSI-98, original CSV rows 2 and 3 report 20 cm/s airflow, 21.5–21.7% starting oxygen for S1 and approximately 21.5% for S2. The archived source records describe SIBAL fabric. NASA's slide 21 annotates the measured fronts at 1.8 mm/s concurrent with flow and 1.3 mm/s opposed. The rates are cited publication measurements, distinct from the original table cells. ·."},{"id":"world-model:world-model-17","title":"FIRST FIRE · The sealed-cabin model and its next validation experiment","url":"#report/world-model","locator":"Compare the model with the Saffire-I record · source line 17","text":"Select Compare both inputs. FIRST FIRE converts the two speeds to 0.18 and 0.13 cm/s and runs two scenarios at the same selected time. It holds all other user inputs fixed and preserves material exhaustion and the assumed oxygen cutoff. At the default conditions and 60 seconds the fronts reach 10.8 and 7.8 cm. These are scenario outputs. The flight rates are inputs, so replaying them supplies no independent test of a propagation prediction. Separate oxygen, flow, specimen geometry, material, gravity and front-position evidence would be necessary to transfer a measurement. The proposed follow-up uses fresh specimens and counterbalances direction order to help distinguish flow effects from thermal history."},{"id":"world-model:world-model-19","title":"FIRST FIRE · The sealed-cabin model and its next validation experiment","url":"#report/world-model","locator":"Compare the model with the Saffire-I record · source line 19","text":"The design takes inspiration from FLUXFIRE's explicit condition matching and FlameBound's presentation of a target beside a source-located condition. The interface, calculations and tests are original to FIRST FIRE. ·."},{"id":"world-model:world-model-36","title":"FIRST FIRE · The sealed-cabin model and its next validation experiment","url":"#report/world-model","locator":"Validation with sensor traces · source line 36","text":"The new implements a prescribed finite tracer pulse in two connected compartments, a remote sensor, and a fit-and-repeat check against published whole-room mixing times.. Further validation requires independent concentration time series."},{"id":"world-model:world-model-38","title":"FIRST FIRE · The sealed-cabin model and its next validation experiment","url":"#report/world-model","locator":"Validation with sensor traces · source line 38","text":"Start with a question the measurements can constrain: given a prescribed release of tracer gas into a ventilated chamber, what concentration should a remote sensor read, and how long should it take to respond? A model of transport can address that question without claiming to predict ignition, flame spread or whether a cabin is safe. It matters for the archive: outlet concentration can rise when flow falls even if the material does not produce more gas. NASA has modeled the vehicle response using measurements from Saffire V."},{"id":"world-model:world-model-42","title":"FIRST FIRE · The sealed-cabin model and its next validation experiment","url":"#report/world-model","locator":"Tracer transport experiment · source line 42","text":"1. Represent the test chamber and a remote sampling volume as connected, well-mixed zones. Store gas mass and species masses in kilograms, temperature in kelvin, pressure in pascals, zone volume in cubic metres, and directional mass flows in kg/s. Distinguish total pressure, oxygen volume fraction and oxygen in a burner stream."},{"id":"world-model:world-model-43","title":"FIRST FIRE · The sealed-cabin model and its next validation experiment","url":"#report/world-model","locator":"Tracer transport experiment · source line 43","text":"2. At each step, compute each species' mass change from incoming and outgoing species flow plus a prescribed source, then update the sensor with its own transport delay and first-order response. The same nonnegative flux exits one zone and enters the next. Specify the initial state, inlet composition, exhaust condition and clock origin; if a necessary condition is missing, request it. Converting a recorded volumetric flow to a mass flow requires its pressure, temperature and composition."},{"id":"world-model:world-model-44","title":"FIRST FIRE · The sealed-cabin model and its next validation experiment","url":"#report/world-model","locator":"Tracer transport experiment · source line 44","text":"3. Begin with an analytic control: for constant density, volume and ventilation, a passive well-mixed tracer decays as C(t) = C₀ exp(−Qt/V) above a zero-concentration inlet, with Q and V expressed in compatible units. Test zero source, a sealed zone, mass balance, positivity and step-size convergence. A seal cannot silently dispose of gas."},{"id":"world-model:world-model-45","title":"FIRST FIRE · The sealed-cabin model and its next validation experiment","url":"#report/world-model","locator":"Tracer transport experiment · source line 45","text":"4. Fit exchange and sensor-response parameters on calibration time series with known release and ventilation. Reserve entire runs or sensors for validation; adjacent video frames cannot be separate train/test samples. Align sample clocks and estimate calibration error. Compare against a single-zone mixing baseline using held-out concentration residuals, onset-time error and interval coverage; publish a residual plot stratified by flow changes. Predeclare acceptable error from measurement uncertainty or an engineering use case before fitting. An attractive animation is not a validation result."},{"id":"world-model:world-model-47","title":"FIRST FIRE · The sealed-cabin model and its next validation experiment","url":"#report/world-model","locator":"Tracer transport experiment · source line 47","text":"The 1,058 archived observation rows are an index, not synchronized full-field trajectories. Obtain sensor streams, a geometry sketch, release history, timestamps, pressure and ventilation calibration before training or fitting. A short burn or sparse summary may make source strength and mixing rate non-identifiable. A plume image without radiometric calibration cannot be converted into arbitrary heat-release units."},{"id":"world-model:world-model-62","title":"FIRST FIRE · The sealed-cabin model and its next validation experiment","url":"#report/world-model","locator":"Chat-to-solver boundary · source line 62","text":"A later tool could accept a versioned Scenario (geometry, units, material/phase, gravity vector, gas state, boundary conditions, measured inputs, provenance and uncertainties) and return a Run (solver/version, input hash, calibration domain, numerical warnings, output time series and validation status). The server validates all fields, enforces model applicability and executes a fixed solver; chat can explain a returned result with a run ID. The interface must label measured, simulated, assumed and unknown separately. The current FM² shared-threshold probability exercise is not a fluid or combustion simulator. Refuse to invent a simulation, certify a material, or silently substitute Earth values when evidence is missing."},{"id":"physics:fire","title":"NASA OCHMO · Fire Protection technical brief","url":"https://www.nasa.gov/wp-content/uploads/2023/12/ochmo-tb-008-fire-protection.pdf","locator":"Overview and Fire Prevention, OCHMO-TB-008","text":"A fire needs fuel, an oxidizer such as oxygen, and sufficient heat for ignition and continued reaction. Heat release can sustain the flame. Removing a necessary condition can extinguish it."},{"id":"physics:flow","title":"NASA OCHMO · Fire Protection technical brief","url":"https://www.nasa.gov/wp-content/uploads/2023/12/ochmo-tb-008-fire-protection.pdf","locator":"Overview, natural convection and ventilation","text":"On Earth, heated gas rises through buoyancy and draws cooler oxygen-bearing air toward a flame. Orbital microgravity greatly reduces this natural convection. Oxygen can diffuse toward the flame, and cabin ventilation can provide forced airflow that changes its shape, spread and persistence."},{"id":"physics:candle","title":"NASA Glenn · Candle Flame, 1 g versus microgravity","url":"https://www.nasa.gov/image-article/candle-flame-1g-vs-microgravity/","locator":"Candle comparison image and caption","text":"An Earth candle tends toward a pointed flame as hot gases rise. In weak flow in orbital microgravity, reduced buoyant convection lets oxygen diffuse in from many directions and the flame can become rounder, blue and less sooty. Ventilation or a different fuel can change that behavior."},{"id":"physics:gravity","title":"NASA Glenn · Zero Gravity Research Facility","url":"https://www.nasa.gov/podcasts/small-steps-giant-leaps/small-steps-giant-leaps-episode-161-nasas-zero-gravity-research-facility/","locator":"Discussion of free fall and drop-tower flame research","text":"Orbiting spacecraft and their contents fall together, producing apparent weightlessness or microgravity. The Moon's surface has partial gravity of about one-sixth of Earth's. Researchers can approximate different regimes using free fall, parabolic aircraft and rotating apparatus. Gravity and observation duration must be recorded separately."},{"id":"physics:risks","title":"NASA · Why NASA is studying flames in space","url":"https://science.nasa.gov/biological-physical/resources/explainers-infographics/why-nasa-is-studying-flames-in-space/","locator":"How to study fire in microgravity","text":"Ground and space experiments help researchers understand flame spread, extinguishment and material behavior, informing spacecraft fire detection, prevention and suppression. Results transfer only within the tested fuel, geometry, atmosphere, gravity, ventilation and measured endpoint."}];
